// questions-defending-systems.js
// Cyber Defense Runner - Defending Systems question bank (100 questions).
// Standalone data file. NOT yet merged into questions.js.
// Distribution: tiers 50 Beginner / 35 Intermediate / 15 Advanced.
//               correct index balanced 25 / 25 / 25 / 25 across A/B/C/D.

const DEFENDING_SYSTEMS_QUESTIONS = [
  { id:"defending-systems-001", tier:"Beginner", topic:"Defending Systems", prompt:"What is the primary job of a firewall?", options:["Filter network traffic using allow and deny rules","Automatically back up files to the cloud each night","Speed up the computer's processor and memory","Assign and reset user account passwords"], correct:0, explain:"A firewall controls which traffic is allowed in or out based on configured rules.", reward:"Firewall Logic" },
  { id:"defending-systems-002", tier:"Intermediate", topic:"Defending Systems", prompt:"What is the key difference between an IDS and an IPS?", options:["An IDS encrypts all of the network's traffic","An IDS detects and alerts, while an IPS can also block","They are two names for exactly the same tool","An IPS only stores logs and never alerts"], correct:1, explain:"An IDS detects and alerts on suspicious traffic; an IPS can actively block it in line.", reward:"Detection Insight" },
  { id:"defending-systems-003", tier:"Beginner", topic:"Defending Systems", prompt:"What does EDR (Endpoint Detection and Response) mainly watch?", options:["How office printers and scanners are doing","Whether network cables are plugged in","Power levels across the building","Activity on endpoints like laptops and servers"], correct:3, explain:"EDR monitors endpoint behavior to detect, investigate, and respond to threats.", reward:"Endpoint Insight" },
  { id:"defending-systems-004", tier:"Beginner", topic:"Defending Systems", prompt:"Why is patching software important?", options:["It changes the theme","It deletes user files","It fixes known security vulnerabilities","It speeds up typing"], correct:2, explain:"Patches fix known bugs and security flaws that attackers could otherwise exploit.", reward:"Patch Discipline" },
  { id:"defending-systems-005", tier:"Beginner", topic:"Defending Systems", prompt:"What is the main purpose of backups?", options:["To make files load faster","To restore data after loss or an attack","To encrypt the CPU","To hide files from users"], correct:1, explain:"Backups let you recover data after deletion, hardware failure, or ransomware.", reward:"Recovery Insight" },
  { id:"defending-systems-006", tier:"Beginner", topic:"Defending Systems", prompt:"What does 'system hardening' mean?", options:["Reducing a system's attack surface by removing or securing weak points","Making the device's physical case much stronger","Turning up the screen brightness for visibility","Adding more memory (RAM) to the computer"], correct:0, explain:"Hardening reduces attack surface by disabling unneeded services, closing ports, and applying secure settings.", reward:"Hardening Focus" },
  { id:"defending-systems-007", tier:"Beginner", topic:"Defending Systems", prompt:"What does the principle of least privilege say?", options:["Give every user full administrator rights","Disable all of the user accounts","Give users only the access they need to do their job","Let everyone share a single login account"], correct:2, explain:"Least privilege limits each user or process to the minimum access required, reducing risk.", reward:"Access Discipline" },
  { id:"defending-systems-008", tier:"Beginner", topic:"Defending Systems", prompt:"Why are logs important for defense?", options:["They make the screen display brighter","They are a replacement for proper backups","They speed up the whole network","They record events so you can detect and investigate problems"], correct:3, explain:"Logs capture activity, providing the evidence needed to detect and investigate incidents.", reward:"Logging Insight" },
  { id:"defending-systems-009", tier:"Beginner", topic:"Defending Systems", prompt:"What is the goal of security monitoring?", options:["To watch systems and alert on suspicious activity","To delete old, unneeded files automatically","To make the CPU run noticeably faster","To design and build company websites"], correct:0, explain:"Monitoring continuously watches systems and raises alerts when something looks wrong.", reward:"Monitoring Focus" },
  { id:"defending-systems-010", tier:"Beginner", topic:"Defending Systems", prompt:"What is vulnerability management?", options:["Ignoring security flaws and hoping for the best","Finding, prioritizing, and fixing security weaknesses over time","Deleting log files to save disk space","Buying new monitors for the team"], correct:1, explain:"Vulnerability management is the ongoing process of identifying, ranking, and fixing weaknesses.", reward:"Vuln Insight" },
  { id:"defending-systems-011", tier:"Beginner", topic:"Defending Systems", prompt:"How does network segmentation help defense?", options:["It makes the Wi-Fi connection faster","It removes the need to patch software","It encrypts every user's password","It limits how far an attacker can move if one part is breached"], correct:3, explain:"Segmentation divides the network so a breach in one zone can't easily spread to others.", reward:"Segmentation Sense" },
  { id:"defending-systems-012", tier:"Intermediate", topic:"Defending Systems", prompt:"What does an application allowlist do?", options:["Blocks only apps already known to be bad","Allows every app to run by default","Permits only approved apps to run and blocks everything else","Encrypts all of the installed apps"], correct:2, explain:"An allowlist permits only explicitly approved applications and blocks all others by default.", reward:"Allowlist Logic" },
  { id:"defending-systems-013", tier:"Beginner", topic:"Defending Systems", prompt:"Why should default passwords be changed during setup?", options:["Because it makes the login process slower","Because default passwords are widely known and easily abused","Because doing so uses up more memory","Because devices require it once a week"], correct:1, explain:"Default credentials are publicly known, so attackers try them first; changing them is basic secure configuration.", reward:"Config Discipline" },
  { id:"defending-systems-014", tier:"Beginner", topic:"Defending Systems", prompt:"What is the main role of antivirus or endpoint protection software?", options:["To detect and block malicious software on a device","To make the internet connection faster","To manage scheduled backups only","To design and lay out networks"], correct:0, explain:"Endpoint protection detects, blocks, and removes malicious software on devices.", reward:"Endpoint Insight" },
  { id:"defending-systems-015", tier:"Beginner", topic:"Defending Systems", prompt:"What is the goal of a recovery plan after an incident?", options:["To assign blame for the incident","To buy a batch of new laptops","To delete all of the logs","To restore normal operations safely and quickly"], correct:3, explain:"Recovery focuses on safely restoring systems and data to normal operation after an incident.", reward:"Recovery Insight" },
  { id:"defending-systems-016", tier:"Intermediate", topic:"Defending Systems", prompt:"What does an 'inbound' firewall rule control?", options:["Traffic coming into the network or host","Only outgoing email","The screen resolution","The CPU temperature"], correct:0, explain:"Inbound rules govern traffic arriving at a host or network from outside.", reward:"Firewall Logic" },
  { id:"defending-systems-017", tier:"Advanced", topic:"Defending Systems", prompt:"A signature-based IDS misses a brand-new attack with no known signature. What could help?", options:["Turning the IDS off","Anomaly- or behavior-based detection","Deleting all rules","Using a louder alert sound"], correct:1, explain:"Behavior or anomaly-based detection can flag unusual activity even without a known signature, catching novel attacks.", reward:"Detection Insight" },
  { id:"defending-systems-018", tier:"Beginner", topic:"Defending Systems", prompt:"What kind of data does EDR continuously collect from endpoints?", options:["Only the desktop wallpaper image and theme","No useful endpoint data at all","Activity such as processes, files, and network connections","Just the device's current battery level"], correct:2, explain:"EDR continuously records endpoint activity like running processes, file changes, and connections to spot threats.", reward:"Endpoint Insight" },
  { id:"defending-systems-019", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is it risky to run software that is 'end of life' and no longer updated?", options:["It quietly uses a little less power","The software simply looks outdated","Older programs actually run faster","Newly found vulnerabilities will never be patched"], correct:3, explain:"End-of-life software stops receiving security updates, so new flaws remain exploitable forever.", reward:"Patch Discipline" },
  { id:"defending-systems-020", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is testing your backups important?", options:["To make the backup files much larger","To deliberately slow down restores","To confirm they can actually be restored when needed","To delete the old backups for space"], correct:2, explain:"A backup is only useful if it restores correctly; testing verifies it works before a real emergency.", reward:"Recovery Insight" },
  { id:"defending-systems-021", tier:"Intermediate", topic:"Defending Systems", prompt:"Disabling unused services and closing unused ports is an example of what?", options:["Increasing attack surface","Reducing attack surface","Backing up data","Encrypting traffic"], correct:1, explain:"Removing unneeded services and ports shrinks the attack surface attackers can target.", reward:"Hardening Focus" },
  { id:"defending-systems-022", tier:"Intermediate", topic:"Defending Systems", prompt:"An app only needs to read one folder but is given full admin rights. Which principle is violated?", options:["Least privilege","Strong encryption","Network segmentation","Patch management"], correct:0, explain:"Granting more access than needed violates least privilege and increases risk if the app is abused.", reward:"Access Discipline" },
  { id:"defending-systems-023", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is it useful to send logs to a central server?", options:["Making the logs disappear faster","Slowing attackers down with extra noise","So logs are preserved even if a device is tampered with","Extending the office Wi-Fi range"], correct:2, explain:"Central logging protects evidence: even if an attacker wipes a device, copies remain for investigation.", reward:"Logging Insight" },
  { id:"defending-systems-024", tier:"Intermediate", topic:"Defending Systems", prompt:"A dashboard shows a sudden spike in failed logins. What should that prompt?", options:["Simply ignoring the failed logins","Shutting the monitoring system down","Buying new monitors for the desk","Investigating possible brute-force or credential attacks"], correct:3, explain:"A spike in failed logins can indicate a brute-force or password attack and should be investigated.", reward:"Monitoring Focus" },
  { id:"defending-systems-025", tier:"Intermediate", topic:"Defending Systems", prompt:"When you can't fix every vulnerability at once, what should guide the order?", options:["Risk and severity, fixing the most dangerous first","Strict alphabetical order of the names","Picking issues completely at random","The file size of each finding"], correct:0, explain:"Prioritize by risk and severity so the most dangerous, exploitable issues are fixed first.", reward:"Vuln Insight" },
  { id:"defending-systems-026", tier:"Intermediate", topic:"Defending Systems", prompt:"Putting servers and user workstations on separate segments mainly helps to do what?", options:["Speed up printing","Limit lateral movement between them","Remove the need for backups","Increase screen size"], correct:1, explain:"Separating servers from workstations limits an attacker's ability to move laterally between them.", reward:"Segmentation Sense" },
  { id:"defending-systems-027", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a denylist (blocklist) approach?", options:["Allow only approved items","Block everything always","Encrypt all items","Block known-bad items while allowing the rest"], correct:3, explain:"A denylist blocks specific known-bad items but allows everything else, the opposite of an allowlist.", reward:"Allowlist Logic" },
  { id:"defending-systems-028", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a 'secure baseline' configuration?", options:["A random, untested set of settings","The fastest possible performance settings","A standard set of hardened settings applied to systems","A single backup copy of the system"], correct:2, explain:"A secure baseline is a documented, hardened configuration applied consistently to reduce risk.", reward:"Config Discipline" },
  { id:"defending-systems-029", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is keeping endpoint protection definitions up to date important?", options:["It frees disk space","It helps detect the latest known threats","It changes the theme","It speeds up boot"], correct:1, explain:"Updated definitions and signatures let endpoint protection recognize newly discovered malware.", reward:"Endpoint Insight" },
  { id:"defending-systems-030", tier:"Intermediate", topic:"Defending Systems", prompt:"What does RTO (Recovery Time Objective) describe?", options:["The target time to restore a system after an outage","The number of users on the system","The total size of a single backup","The processing speed of the CPU"], correct:0, explain:"RTO is the goal for how quickly a system or service should be restored after disruption.", reward:"Recovery Insight" },
  { id:"defending-systems-031", tier:"Advanced", topic:"Defending Systems", prompt:"A web server should be reachable on 443 but is also exposing a database port to the internet. What is the best firewall fix?", options:["Open every single port just to be safe","Disable the firewall on the server completely","Allow 443 and block the database port from the internet","Block port 443 so the site is unreachable"], correct:2, explain:"Only the needed service (443) should be exposed; the database port should be blocked from the internet to reduce attack surface.", reward:"Firewall Logic" },
  { id:"defending-systems-032", tier:"Beginner", topic:"Defending Systems", prompt:"Where is a network IDS/IPS typically placed?", options:["Hidden away inside the office printer","Plugged directly into the keyboard port","Only ever running in the public cloud","Where it can watch network traffic, such as near the perimeter"], correct:3, explain:"Network IDS/IPS sits where it can inspect traffic, often at the network boundary or key chokepoints.", reward:"Detection Insight" },
  { id:"defending-systems-033", tier:"Intermediate", topic:"Defending Systems", prompt:"EDR flags a normal admin tool being used at 3 a.m. from an unusual account. Why might this matter?", options:["Legitimate tools can be abused by attackers (living off the land)","Admin tools are always perfectly safe","EDR alerts are never wrong about this","The time of day simply never matters"], correct:0, explain:"Attackers often abuse legitimate tools; unusual context like time and account can reveal misuse of trusted software.", reward:"Endpoint Insight" },
  { id:"defending-systems-034", tier:"Advanced", topic:"Defending Systems", prompt:"Why might an organization test patches in a staging environment before wide deployment?", options:["To deliberately make the patching process slower","To catch patches that could break critical systems before they reach production","To prove that patches never cause any problems at all","To skip security checks entirely and save time"], correct:1, explain:"Testing patches first catches compatibility or stability problems before they disrupt production systems.", reward:"Patch Discipline" },
  { id:"defending-systems-035", tier:"Beginner", topic:"Defending Systems", prompt:"What is an 'offline' or offsite backup especially useful against?", options:["Slow keyboard typing during the day","Screens that are too bright to read","Computer fans running a bit loud","Ransomware that tries to encrypt connected backups"], correct:3, explain:"Offline or offsite backups are isolated, so ransomware that encrypts live systems can't reach them.", reward:"Recovery Insight" },
  { id:"defending-systems-036", tier:"Beginner", topic:"Defending Systems", prompt:"Removing default sample accounts and demo files during setup is part of what?", options:["Backing up","Monitoring","Hardening","Encrypting"], correct:2, explain:"Cleaning up default accounts and sample content removes easy footholds, part of hardening.", reward:"Hardening Focus" },
  { id:"defending-systems-037", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is using a separate admin account, not your everyday account, a good practice?", options:["It generally looks more professional to other people","If your daily account is compromised, the attacker doesn't automatically get admin rights","Your available storage space is effectively doubled overnight","The computer simply runs noticeably faster overall"], correct:1, explain:"Separating admin from daily-use accounts limits damage: compromising the everyday account doesn't grant admin power.", reward:"Access Discipline" },
  { id:"defending-systems-038", tier:"Beginner", topic:"Defending Systems", prompt:"Which of these is most useful to record in security logs?", options:["Login attempts and access events","The desktop wallpaper","The mouse pointer color","Screen brightness"], correct:0, explain:"Authentication and access events are key security signals worth logging for detection and investigation.", reward:"Logging Insight" },
  { id:"defending-systems-039", tier:"Beginner", topic:"Defending Systems", prompt:"What is an 'alert' in security monitoring?", options:["A spare backup file kept on disk","A specific type of network cable","A notification that something may need attention","A password used to log in"], correct:2, explain:"An alert notifies analysts that a condition or event may require investigation or action.", reward:"Monitoring Focus" },
  { id:"defending-systems-040", tier:"Beginner", topic:"Defending Systems", prompt:"What does a vulnerability scanner do?", options:["Encrypts traffic across the whole network","Backs up important company data","Blocks all incoming and outgoing traffic","Checks systems for known weaknesses and reports them"], correct:3, explain:"A scanner inspects systems for known vulnerabilities and produces a report to guide fixes.", reward:"Vuln Insight" },
  { id:"defending-systems-041", tier:"Intermediate", topic:"Defending Systems", prompt:"A 'DMZ' (demilitarized zone) in a network is used to do what?", options:["Place public-facing services in a separate zone from the internal network","Store all of the company's passwords in one place","Make the office Wi-Fi connection run faster","Turn off the network firewalls completely"], correct:0, explain:"A DMZ isolates internet-facing services so a compromise there doesn't directly expose the internal network.", reward:"Segmentation Sense" },
  { id:"defending-systems-042", tier:"Beginner", topic:"Defending Systems", prompt:"Which approach is generally more secure but harder to maintain?", options:["No rules at all","Allowlisting with default deny","Turning off the firewall","Sharing accounts"], correct:1, explain:"Allowlisting (default deny) is more secure because only approved items run, though it takes more effort to maintain.", reward:"Allowlist Logic" },
  { id:"defending-systems-043", tier:"Beginner", topic:"Defending Systems", prompt:"Disabling an unused remote-access feature is an example of what?", options:["Backing up the system's files","Monitoring the network for alerts","Patching the operating system","Secure configuration that reduces attack surface"], correct:3, explain:"Turning off features you don't need is secure configuration that shrinks the attack surface.", reward:"Config Discipline" },
  { id:"defending-systems-044", tier:"Beginner", topic:"Defending Systems", prompt:"What is a 'quarantine' in endpoint protection?", options:["A folder used only to store backups","A faster performance mode for the CPU","Isolating a suspicious file so it can't run or spread","One specific type of network firewall"], correct:2, explain:"Quarantine isolates a suspicious or malicious file so it cannot execute or spread while it is reviewed.", reward:"Endpoint Insight" },
  { id:"defending-systems-045", tier:"Beginner", topic:"Defending Systems", prompt:"What does RPO (Recovery Point Objective) describe?", options:["The current speed of the network","How much data loss is acceptable, measured in time","How many administrators there are","The physical size of the firewall"], correct:1, explain:"RPO defines the maximum acceptable amount of data loss, often expressed as how far back the last good backup must be.", reward:"Recovery Insight" },
  { id:"defending-systems-046", tier:"Beginner", topic:"Defending Systems", prompt:"An 'outbound' firewall rule can help do what?", options:["Control or block traffic leaving a host, such as malware calling home","Make file downloads complete much faster","Assign IP addresses to brand-new devices","Back up important files to an external disk"], correct:0, explain:"Outbound rules restrict traffic leaving a device, which can stop malware from contacting its server.", reward:"Firewall Logic" },
  { id:"defending-systems-047", tier:"Beginner", topic:"Defending Systems", prompt:"An IPS keeps blocking legitimate traffic it wrongly thinks is malicious. What is this called?", options:["A true positive","A false positive","A backup","A patch"], correct:1, explain:"A false positive is benign activity wrongly flagged as malicious; tuning reduces these.", reward:"Detection Insight" },
  { id:"defending-systems-048", tier:"Advanced", topic:"Defending Systems", prompt:"What does 'host isolation' by EDR accomplish during an active compromise?", options:["It immediately deletes the device's entire operating system","It makes the affected device run much faster than before","It encrypts all of the user's personal files and folders","It cuts the device's network access to contain the threat while allowing investigation"], correct:3, explain:"Host isolation blocks the endpoint's network communications to stop spread while responders investigate.", reward:"Endpoint Insight" },
  { id:"defending-systems-049", tier:"Beginner", topic:"Defending Systems", prompt:"What is a 'security update'?", options:["A fix released to close a security weakness","A brand-new desktop wallpaper image","A larger replacement hard drive","A faster, more responsive mouse"], correct:0, explain:"A security update patches a specific weakness so attackers can no longer exploit it.", reward:"Patch Discipline" },
  { id:"defending-systems-050", tier:"Intermediate", topic:"Defending Systems", prompt:"What is the idea behind the '3-2-1' backup approach?", options:["Three admins, two passwords, and one server","Three copies of data, on two types of media, with one kept offsite","Three firewalls placed one after another","One backup copy is always enough"], correct:1, explain:"3-2-1 means keep three copies, on two different media, with one stored offsite, improving resilience.", reward:"Recovery Insight" },
  { id:"defending-systems-051", tier:"Beginner", topic:"Defending Systems", prompt:"Why is enabling automatic screen lock part of hardening a workstation?", options:["It only saves a small amount of power","It makes logging in noticeably faster","It changes the desktop theme to dark","It prevents others from using an unattended, logged-in session"], correct:3, explain:"Auto screen lock stops someone from misusing a device left logged in and unattended.", reward:"Hardening Focus" },
  { id:"defending-systems-052", tier:"Beginner", topic:"Defending Systems", prompt:"Promptly removing a former employee's accounts supports which idea?", options:["More detailed logging of events","Faster, more reliable backups","Least privilege and removing unused access","Bigger and stronger firewalls"], correct:2, explain:"Disabling unneeded accounts removes access that could be abused, supporting least privilege.", reward:"Access Discipline" },
  { id:"defending-systems-053", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should log timestamps use a synchronized, consistent time source?", options:["It saves a noticeable amount of disk space","So events across systems can be correlated into an accurate timeline","Colorful logs are much easier to read quickly","The CPU runs a little faster as a result"], correct:1, explain:"Synchronized time lets analysts line up events from different systems into a correct sequence.", reward:"Logging Insight" },
  { id:"defending-systems-054", tier:"Advanced", topic:"Defending Systems", prompt:"Why can too many low-value alerts be a security problem?", options:["Alert fatigue can cause analysts to miss the important ones","More alerts always make systems faster","Extra alerts can replace regular backups","More alerts are always strictly better"], correct:0, explain:"Excessive noisy alerts cause fatigue, so genuinely serious alerts can be overlooked; tuning is essential.", reward:"Monitoring Focus" },
  { id:"defending-systems-055", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is an asset inventory important for vulnerability management?", options:["It only makes the scans run slower","Inventories are only useful for accounting","You can't protect or patch systems you don't know exist","It is a complete replacement for patching"], correct:2, explain:"You can only manage vulnerabilities on assets you know about; an inventory ensures nothing is missed.", reward:"Vuln Insight" },
  { id:"defending-systems-056", tier:"Advanced", topic:"Defending Systems", prompt:"How does microsegmentation differ from traditional network segmentation?", options:["It removes the need for firewalls anywhere on the network","It can only ever be applied to wireless Wi-Fi networks","It automatically deletes the system's event logs","It enforces fine-grained controls down to individual workloads, not just large zones"], correct:3, explain:"Microsegmentation applies granular, per-workload controls, limiting movement even within a zone.", reward:"Segmentation Sense" },
  { id:"defending-systems-057", tier:"Beginner", topic:"Defending Systems", prompt:"An allowlist of approved software mainly reduces the risk of what?", options:["Unapproved or malicious programs running","Users typing on the keyboard slowly","Screens being a little too bright","Damage to the network cabling"], correct:0, explain:"If only approved software can run, unknown or malicious programs are blocked by default.", reward:"Allowlist Logic" },
  { id:"defending-systems-058", tier:"Advanced", topic:"Defending Systems", prompt:"Why is 'configuration drift' a security concern over time?", options:["It actually makes the affected systems run faster","Backups quietly get better and better over time","Systems gradually move away from their secure baseline, reopening risks","Everything on the system becomes fully encrypted"], correct:2, explain:"Drift means systems slowly diverge from the hardened baseline, reintroducing weaknesses unless monitored.", reward:"Config Discipline" },
  { id:"defending-systems-059", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is endpoint protection alone not a complete defense?", options:["It is generally far too cheap to be useful","Endpoint tools can only ever run on servers","A single tool can fully replace all the others","Layered defenses are needed because no single control catches everything"], correct:3, explain:"No single tool stops every threat; defense in depth layers controls so others catch what one misses.", reward:"Endpoint Insight" },
  { id:"defending-systems-060", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should an incident recovery plan be documented and practiced beforehand?", options:["So responders can act quickly and correctly under pressure","To make the team use more paper","Because such plans are legally banned","To deliberately slow down the recovery"], correct:0, explain:"A practiced, written plan lets the team respond fast and consistently instead of improvising during a crisis.", reward:"Recovery Insight" },
  { id:"defending-systems-061", tier:"Beginner", topic:"Defending Systems", prompt:"A firewall rule's 'deny' action does what to matching traffic?", options:["Speeds it up","Blocks it","Encrypts it","Logs it only"], correct:1, explain:"A deny rule blocks traffic that matches its conditions.", reward:"Firewall Logic" },
  { id:"defending-systems-062", tier:"Beginner", topic:"Defending Systems", prompt:"What is a 'true positive' for an IDS?", options:["A real threat correctly detected and alerted","A harmless event flagged as bad","A missed attack","A backup job"], correct:0, explain:"A true positive is genuine malicious activity that the IDS correctly identifies and alerts on.", reward:"Detection Insight" },
  { id:"defending-systems-063", tier:"Intermediate", topic:"Defending Systems", prompt:"EDR records detailed endpoint activity. How does this help after an incident?", options:["It makes the screen brighter","It charges the battery","It provides a timeline of what the threat did","It deletes all malware forever automatically"], correct:2, explain:"Recorded telemetry lets responders reconstruct what happened and how far the threat spread.", reward:"Endpoint Insight" },
  { id:"defending-systems-064", tier:"Beginner", topic:"Defending Systems", prompt:"What is a 'zero-day' vulnerability?", options:["A bug that is completely harmless","A patch that was released early","A specific type of backup file","A flaw being exploited before a fix is available"], correct:3, explain:"A zero-day is a vulnerability exploited before the vendor has released a patch.", reward:"Patch Discipline" },
  { id:"defending-systems-065", tier:"Beginner", topic:"Defending Systems", prompt:"Encrypting backups helps protect against what?", options:["Someone reading the backup data if it is stolen","Backups restoring more slowly than usual","Screens that are far too bright","Files that are very large in size"], correct:0, explain:"Encryption keeps backup contents unreadable to anyone who steals or finds the backup media.", reward:"Recovery Insight" },
  { id:"defending-systems-066", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is removing local administrator rights from everyday users a strong hardening step?", options:["It noticeably speeds up the mouse pointer","It limits malware to user-level actions if a user is compromised","It increases the available storage space","It turns off automatic backups"], correct:1, explain:"Without local admin, malware running as that user can't easily make system-wide changes, limiting damage.", reward:"Hardening Focus" },
  { id:"defending-systems-067", tier:"Beginner", topic:"Defending Systems", prompt:"A 'service account' used by an application should be given what level of access?", options:["Full domain admin always","Whatever is easiest","Shared with real users","Only the specific access the service needs"], correct:3, explain:"Service accounts should follow least privilege, holding only the permissions the service actually requires.", reward:"Access Discipline" },
  { id:"defending-systems-068", tier:"Intermediate", topic:"Defending Systems", prompt:"Why might an attacker try to clear or disable logs?", options:["To free disk space for the victim","To improve performance","To hide their activity and slow investigation","To help defenders"], correct:2, explain:"Clearing logs removes evidence of the attacker's actions, making detection and investigation harder.", reward:"Logging Insight" },
  { id:"defending-systems-069", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a 'baseline' of normal activity useful for in monitoring?", options:["Making the alert sounds much louder","Spotting deviations that may indicate a problem","Acting as a replacement for backups","Speeding up the computer's CPU"], correct:1, explain:"Knowing what 'normal' looks like helps you notice abnormal activity that could signal an incident.", reward:"Monitoring Focus" },
  { id:"defending-systems-070", tier:"Advanced", topic:"Defending Systems", prompt:"Why is a severity score (such as CVSS) useful in vulnerability management?", options:["It gives a standardized rating to help prioritize fixes","It encrypts the whole system automatically","It backs up the company's data","It blocks all network traffic"], correct:0, explain:"A standardized severity score lets teams compare and prioritize vulnerabilities consistently.", reward:"Vuln Insight" },
  { id:"defending-systems-071", tier:"Intermediate", topic:"Defending Systems", prompt:"Keeping payment systems on their own isolated segment mainly helps to do what?", options:["Make the payment systems run faster","Give them public IP addresses","Limit exposure and contain risk to sensitive systems","Remove the need to patch them"], correct:2, explain:"Isolating sensitive systems reduces their exposure and contains risk if other areas are breached.", reward:"Segmentation Sense" },
  { id:"defending-systems-072", tier:"Advanced", topic:"Defending Systems", prompt:"What is a practical drawback of strict application allowlisting?", options:["It reliably blocks all known malware","Allowlisting is simply too secure to actually use","It encrypts all of the files stored on disk","Legitimate new or updated apps may be blocked until they are approved"], correct:3, explain:"Allowlisting can block valid new or updated software until it is reviewed and approved, requiring ongoing maintenance.", reward:"Allowlist Logic" },
  { id:"defending-systems-073", tier:"Advanced", topic:"Defending Systems", prompt:"Why are configuration management tools helpful for secure configuration at scale?", options:["They enforce consistent hardened settings across many systems automatically","They quietly delete the system's event logs","They act as a full replacement for firewalls","They make the graphics card (GPU) run faster"], correct:0, explain:"Configuration management applies and maintains consistent, hardened settings across many systems, preventing drift.", reward:"Config Discipline" },
  { id:"defending-systems-074", tier:"Advanced", topic:"Defending Systems", prompt:"Why is 'behavior-based' endpoint protection valuable against new malware?", options:["It relies only on signature lists","It never needs any updates at all","It can flag malicious actions even without a known signature","It turns off the network connection"], correct:2, explain:"Behavior-based detection watches what software does, catching novel malware that signature lists haven't seen yet.", reward:"Endpoint Insight" },
  { id:"defending-systems-075", tier:"Intermediate", topic:"Defending Systems", prompt:"After containing an incident, why verify systems are clean before restoring service?", options:["To deliberately waste some time","Because cleaning systems is illegal","To delete the existing backups","To avoid restoring with the attacker still present"], correct:3, explain:"Restoring before verifying could bring systems back online while the threat is still active, causing reinfection.", reward:"Recovery Insight" },
  { id:"defending-systems-076", tier:"Intermediate", topic:"Defending Systems", prompt:"What does a 'next-generation firewall' add over a basic packet filter?", options:["Application awareness and deeper inspection of traffic","A slightly faster cooling fan","Extra built-in backup storage","A noticeably bigger display screen"], correct:0, explain:"Next-gen firewalls inspect at the application level and add features like intrusion prevention, beyond simple port and IP filtering.", reward:"Firewall Logic" },
  { id:"defending-systems-077", tier:"Intermediate", topic:"Defending Systems", prompt:"Why must IDS/IPS rules be tuned over time?", options:["To deliberately make them run slower","To reduce false positives and keep detections relevant","To delete the system's stored logs","To turn off all of the alerts"], correct:1, explain:"Tuning reduces noisy false positives and keeps detection focused on real, current threats.", reward:"Detection Insight" },
  { id:"defending-systems-078", tier:"Intermediate", topic:"Defending Systems", prompt:"How does EDR differ from traditional antivirus?", options:["It only ever scans incoming and outgoing email messages","It has essentially no real threat-detection ability at all","It adds continuous monitoring, investigation, and response, not just signature scanning","It is exactly the same thing as plain old antivirus"], correct:2, explain:"EDR goes beyond signature scanning by continuously recording activity and enabling investigation and response.", reward:"Endpoint Insight" },
  { id:"defending-systems-079", tier:"Beginner", topic:"Defending Systems", prompt:"What is a good habit for keeping a personal device secure?", options:["Never restart the device at all","Disable all of the updates","Reuse one password everywhere","Install updates promptly when they are released"], correct:3, explain:"Applying updates promptly closes known security holes attackers actively target.", reward:"Patch Discipline" },
  { id:"defending-systems-080", tier:"Intermediate", topic:"Defending Systems", prompt:"Why keep multiple backup versions over time, not just the latest?", options:["To use up much more disk space just for the fun of it","To deliberately slow down every restore","So you can recover from before a problem, like silent corruption, occurred","Because backups simply never get corrupted"], correct:2, explain:"Versioned backups let you restore from a point before corruption or an attack happened, not just the most recent copy.", reward:"Recovery Insight" },
  { id:"defending-systems-081", tier:"Beginner", topic:"Defending Systems", prompt:"Turning off an unused Bluetooth or remote feature on a device is an example of what?", options:["Reducing the attack surface","Adding a vulnerability","Backing up","Increasing privilege"], correct:0, explain:"Disabling features you don't use removes potential entry points, reducing attack surface.", reward:"Hardening Focus" },
  { id:"defending-systems-082", tier:"Beginner", topic:"Defending Systems", prompt:"Role-based access control (RBAC) supports least privilege by doing what?", options:["Giving everyone the same rights","Granting permissions based on a user's job role","Removing all access","Sharing one admin account"], correct:1, explain:"RBAC assigns permissions by role, so users get just the access their job needs.", reward:"Access Discipline" },
  { id:"defending-systems-083", tier:"Beginner", topic:"Defending Systems", prompt:"Which is a benefit of keeping logs for a reasonable period?", options:["The Wi-Fi connection becomes faster","Computer screens become much brighter","Log files take up much less space","You can investigate incidents discovered days or weeks later"], correct:3, explain:"Retained logs let you look back and investigate incidents that are only noticed later.", reward:"Logging Insight" },
  { id:"defending-systems-084", tier:"Beginner", topic:"Defending Systems", prompt:"What is the purpose of a SIEM in monitoring?", options:["To act as a replacement for all of the backups","To charge connected devices more quickly","To collect and correlate logs and alerts from many sources in one place","To design and lay out company networks"], correct:2, explain:"A SIEM aggregates and correlates events from many systems, helping detect and investigate threats centrally.", reward:"Monitoring Focus" },
  { id:"defending-systems-085", tier:"Beginner", topic:"Defending Systems", prompt:"After patching a vulnerability, what is a good final step?", options:["Delete the affected asset entirely","Rescan or verify that the fix actually resolved it","Ignore the issue from now on","Turn off the network firewall"], correct:1, explain:"Re-scanning or verifying confirms the vulnerability is truly fixed and nothing was missed.", reward:"Vuln Insight" },
  { id:"defending-systems-086", tier:"Advanced", topic:"Defending Systems", prompt:"In a 'zero trust' approach, how is internal network traffic treated?", options:["It is verified and not automatically trusted just for being internal","It is always trusted without any extra checks","It is never recorded in the system logs","It is always blocked outright by default"], correct:0, explain:"Zero trust verifies every request regardless of location, rather than trusting traffic just because it is inside the network.", reward:"Segmentation Sense" },
  { id:"defending-systems-087", tier:"Advanced", topic:"Defending Systems", prompt:"Why can blocking by file hash alone be insufficient against malware?", options:["Using file hashes is actually illegal","Attackers can slightly change a file to produce a new hash","A file's hash never changes at all","Hash blocking simply blocks too much"], correct:1, explain:"A tiny change to malware yields a new hash, bypassing a denylist that only blocks specific known hashes.", reward:"Allowlist Logic" },
  { id:"defending-systems-088", tier:"Intermediate", topic:"Defending Systems", prompt:"Why are security benchmarks or hardening guides useful?", options:["They make the GPU run noticeably faster","They are a full replacement for antivirus","They exist only for decoration","They provide vetted, consistent settings to harden systems"], correct:3, explain:"Established hardening benchmarks give tested, consistent secure settings to apply across systems.", reward:"Config Discipline" },
  { id:"defending-systems-089", tier:"Advanced", topic:"Defending Systems", prompt:"Why is application control combined with endpoint protection stronger than either alone?", options:["One of them on its own is always enough","They remove the need to patch systems at all","Together they block unknown programs and detect malicious behavior","The two tools simply cancel each other out"], correct:2, explain:"Combining what is allowed to run with behavior detection layers defenses for better coverage.", reward:"Endpoint Insight" },
  { id:"defending-systems-090", tier:"Advanced", topic:"Defending Systems", prompt:"Why are immutable backups especially valuable against ransomware?", options:["They load and restore much faster than usual","They cannot be altered or deleted for a set period, even by an attacker","They take up almost no storage space at all","They act as a replacement for firewalls"], correct:1, explain:"Immutable backups can't be changed or deleted during their retention window, so ransomware can't destroy them.", reward:"Recovery Insight" },
  { id:"defending-systems-091", tier:"Intermediate", topic:"Defending Systems", prompt:"What is an important consideration about firewall rule order?", options:["The colors assigned to rules matter most","Rules are simply applied in random order","The order of the rules never matters at all","Rules are evaluated in order, so a broad allow can override a later deny"], correct:3, explain:"Firewalls evaluate rules in order; a permissive rule placed too early can unintentionally override stricter rules below it.", reward:"Firewall Logic" },
  { id:"defending-systems-092", tier:"Beginner", topic:"Defending Systems", prompt:"An IPS sits 'in line' with traffic. What does that let it do that a passive IDS cannot?", options:["Change the desktop wallpaper image","Run games much more smoothly","Actively block malicious traffic in real time","Store extra system backups"], correct:2, explain:"Because an IPS is in the traffic path, it can drop or block malicious packets, not just alert.", reward:"Detection Insight" },
  { id:"defending-systems-093", tier:"Beginner", topic:"Defending Systems", prompt:"What is an 'endpoint' in the context of EDR?", options:["A standard Ethernet network cable","A device like a laptop, desktop, or server","A public-facing company website","A user's account login password"], correct:1, explain:"An endpoint is a user or server device, such as a laptop, desktop, or server, that EDR protects.", reward:"Endpoint Insight" },
  { id:"defending-systems-094", tier:"Beginner", topic:"Defending Systems", prompt:"What is 'patch management'?", options:["A process to track, test, and apply software updates","A method for deleting unwanted files","A simple way to back up your data","A specific type of network firewall"], correct:0, explain:"Patch management is the organized process of finding, testing, and deploying updates across systems.", reward:"Patch Discipline" },
  { id:"defending-systems-095", tier:"Beginner", topic:"Defending Systems", prompt:"Where is the safest place to keep at least one backup copy?", options:["On the very same disk as the original","Only inside the very same folder","Separate from the original, such as offsite or offline","Nowhere in particular is fine"], correct:2, explain:"Keeping a copy separate (offsite or offline) protects it if the original system is lost, damaged, or attacked.", reward:"Recovery Insight" },
  { id:"defending-systems-096", tier:"Beginner", topic:"Defending Systems", prompt:"Why is enabling a host-based firewall on each device a hardening measure?", options:["It makes the cooling fan run quieter","It charges the device much faster","It changes the desktop theme to dark","It adds a per-device layer that limits unwanted connections"], correct:3, explain:"Host firewalls add an extra layer, controlling connections even if network defenses are bypassed.", reward:"Hardening Focus" },
  { id:"defending-systems-097", tier:"Beginner", topic:"Defending Systems", prompt:"'Privilege creep' is the problem where users do what over time?", options:["Accumulate access they no longer need","Lose all of their access","Forget their passwords","Change desks"], correct:0, explain:"Privilege creep is the gradual buildup of unnecessary permissions; periodic access reviews remove them.", reward:"Access Discipline" },
  { id:"defending-systems-098", tier:"Beginner", topic:"Defending Systems", prompt:"Why is protecting the integrity of logs important?", options:["It makes the log files more colorful to read","So logs can be trusted as accurate evidence during investigations","Wi-Fi speeds improve noticeably afterward","Disk space usage goes down significantly"], correct:1, explain:"If logs can be secretly altered, they can't be trusted; protecting their integrity keeps them reliable as evidence.", reward:"Logging Insight" },
  { id:"defending-systems-099", tier:"Beginner", topic:"Defending Systems", prompt:"What should typically happen when a high-severity security alert fires?", options:["Ignore it for a week","Delete the monitoring tool","Turn off logging","An analyst investigates and responds promptly"], correct:3, explain:"High-severity alerts should trigger prompt investigation and response to limit potential damage.", reward:"Monitoring Focus" },
  { id:"defending-systems-100", tier:"Beginner", topic:"Defending Systems", prompt:"What is 'remediation' in vulnerability management?", options:["Making a spare backup copy of the data","Adding another network cable","Fixing or reducing the risk of a found vulnerability","Performing a standard password reset"], correct:2, explain:"Remediation is the action taken to fix or reduce the risk of an identified vulnerability, such as patching or reconfiguring.", reward:"Vuln Insight" },
  { id:"defending-systems-101", tier:"Beginner", topic:"Defending Systems", prompt:"What is the main purpose of patching systems?", options:["To fix vulnerabilities, bugs, and stability issues","To make passwords shorter","To delete all logs","To replace user training"], correct:0, explain:"Patching reduces known weaknesses attackers may exploit.", reward:"Patch Sense" },
  { id:"defending-systems-102", tier:"Beginner", topic:"Defending Systems", prompt:"Why should operating systems be kept updated?", options:["Updates always remove the need for backups","Updates can fix security flaws and improve reliability","Updates disable all user accounts","Updates make phishing impossible"], correct:1, explain:"System updates often include security fixes and reliability improvements.", reward:"Patch Sense" },
  { id:"defending-systems-103", tier:"Beginner", topic:"Defending Systems", prompt:"What is a vulnerability?", options:["A normal user login","A completed backup","A weakness that could be exploited or misused","A firewall dashboard color"], correct:2, explain:"A vulnerability is a weakness in software, configuration, or process.", reward:"Vulnerability Basics" },
  { id:"defending-systems-104", tier:"Beginner", topic:"Defending Systems", prompt:"Why is vulnerability management important?", options:["It removes the need for monitoring","It makes every system public","It replaces authentication","It helps find, prioritize, and fix weaknesses before they are abused"], correct:3, explain:"Vulnerability management turns discovered weaknesses into prioritized fixes.", reward:"Vulnerability Basics" },
  { id:"defending-systems-105", tier:"Beginner", topic:"Defending Systems", prompt:"What is system hardening?", options:["Reducing unnecessary services, permissions, and risky settings","Turning computers physically harder","Deleting all user files","Allowing every inbound connection"], correct:0, explain:"Hardening reduces attack surface by making systems more secure by default.", reward:"Hardening Sense" },
  { id:"defending-systems-106", tier:"Beginner", topic:"Defending Systems", prompt:"Why should unused services be disabled?", options:["Unused services always improve performance","They may expose unnecessary attack surface","They make backups impossible","They replace endpoint detection"], correct:1, explain:"Services that are not needed should not remain reachable or running.", reward:"Attack Surface" },
  { id:"defending-systems-107", tier:"Beginner", topic:"Defending Systems", prompt:"What is attack surface?", options:["The physical size of a server","The number of monitors in a SOC","The exposed systems, services, accounts, and paths attackers could target","The color of a firewall rule"], correct:2, explain:"Attack surface is what an attacker could potentially reach or abuse.", reward:"Attack Surface" },
  { id:"defending-systems-108", tier:"Beginner", topic:"Defending Systems", prompt:"Why reduce attack surface?", options:["To make systems impossible to update","To remove all security logs","To make users share passwords","To leave fewer unnecessary paths for attackers to target"], correct:3, explain:"Less exposure usually means fewer opportunities for misuse or exploitation.", reward:"Attack Surface" },
  { id:"defending-systems-109", tier:"Beginner", topic:"Defending Systems", prompt:"What is endpoint protection used for?", options:["Detecting, blocking, or responding to suspicious activity on devices","Creating DNS records","Replacing backups","Changing monitor brightness"], correct:0, explain:"Endpoint protection helps defend laptops, servers, and workstations.", reward:"Endpoint Defense" },
  { id:"defending-systems-110", tier:"Beginner", topic:"Defending Systems", prompt:"What is EDR?", options:["A printer management protocol","Endpoint Detection and Response","External DNS Resolver","Encrypted Desktop Router"], correct:1, explain:"EDR tools monitor endpoints and support investigation and response.", reward:"EDR Basics" },
  { id:"defending-systems-111", tier:"Beginner", topic:"Defending Systems", prompt:"Why are endpoint logs useful?", options:["They replace all network logs","They prevent all malware automatically","They show processes, files, users, and activity on a device","They make phishing impossible"], correct:2, explain:"Endpoint logs provide evidence about what happened on a host.", reward:"Endpoint Logs" },
  { id:"defending-systems-112", tier:"Beginner", topic:"Defending Systems", prompt:"What is antivirus mainly designed to do?", options:["Assign IP addresses","Create firewall rules","Manage user calendars","Detect or block known malicious files or behavior"], correct:3, explain:"Antivirus helps detect and prevent malware, though it is not enough by itself.", reward:"Malware Defense" },
  { id:"defending-systems-113", tier:"Beginner", topic:"Defending Systems", prompt:"Why should security tools stay enabled?", options:["Disabled tools reduce visibility and protection","Disabled tools always improve safety","Disabled tools prevent phishing","Disabled tools replace backups"], correct:0, explain:"Security tools provide prevention, detection, and response visibility.", reward:"Defense Evasion" },
  { id:"defending-systems-114", tier:"Beginner", topic:"Defending Systems", prompt:"Why is disabling security software suspicious?", options:["It always means a normal update","Attackers may disable defenses to avoid detection","It makes systems more secure","It prevents malware execution"], correct:1, explain:"Security tool tampering can be a defense-evasion sign.", reward:"Defense Evasion" },
  { id:"defending-systems-115", tier:"Beginner", topic:"Defending Systems", prompt:"What is least privilege?", options:["Giving users administrator rights by default","Removing all user accounts","Giving users and systems only the access they need","Disabling authentication entirely"], correct:2, explain:"Least privilege limits damage from mistakes or compromise.", reward:"Least Privilege" },
  { id:"defending-systems-116", tier:"Beginner", topic:"Defending Systems", prompt:"Why should standard users not have local admin rights by default?", options:["Admin rights make usernames shorter","Admin rights prevent all malware","Admin rights replace MFA","Admin rights can allow wider system changes if the account is misused"], correct:3, explain:"Limiting admin rights reduces the impact of compromise or accidental changes.", reward:"Least Privilege" },
  { id:"defending-systems-117", tier:"Beginner", topic:"Defending Systems", prompt:"What is MFA used for?", options:["Adding an extra verification step beyond just a password","Deleting old accounts","Encrypting hard drives automatically","Replacing all access reviews"], correct:0, explain:"MFA makes stolen passwords less useful by requiring another factor.", reward:"MFA Shield" },
  { id:"defending-systems-118", tier:"Beginner", topic:"Defending Systems", prompt:"Why are strong passwords still important even with MFA?", options:["MFA disables passwords entirely","Weak passwords can still increase risk, especially where MFA is missing or bypassed","Passwords are never attacked","Strong passwords remove the need for monitoring"], correct:1, explain:"MFA helps, but passwords still matter as one layer of defense.", reward:"Password Defense" },
  { id:"defending-systems-119", tier:"Beginner", topic:"Defending Systems", prompt:"What is account lockout designed to reduce?", options:["Normal web browsing","Backup storage","Repeated password guessing attempts","Operating system updates"], correct:2, explain:"Lockout policies can slow or limit brute-force attempts.", reward:"Login Defense" },
  { id:"defending-systems-120", tier:"Beginner", topic:"Defending Systems", prompt:"Why should old or unused accounts be disabled?", options:["They make dashboards look messy","They improve performance automatically","They make patching unnecessary","They may be forgotten access paths attackers can abuse"], correct:3, explain:"Stale accounts increase unnecessary access risk.", reward:"Account Hygiene" },
  { id:"defending-systems-121", tier:"Beginner", topic:"Defending Systems", prompt:"What is a backup?", options:["A copy of data that can be used for recovery","A firewall alert","A password reset form","A DNS query"], correct:0, explain:"Backups help restore data after deletion, corruption, or ransomware.", reward:"Backup Basics" },
  { id:"defending-systems-122", tier:"Beginner", topic:"Defending Systems", prompt:"Why should backups be tested?", options:["Testing backups deletes production data","Untested backups may fail when recovery is needed","Testing backups disables security logs","Backups never fail"], correct:1, explain:"A backup is only useful if it can actually be restored.", reward:"Backup Basics" },
  { id:"defending-systems-123", tier:"Beginner", topic:"Defending Systems", prompt:"What is the purpose of offline or immutable backups?", options:["To make backups impossible to restore","To replace endpoint security","To protect backups from being modified or destroyed by attackers","To disable network access permanently"], correct:2, explain:"Offline or immutable backups can survive ransomware or destructive activity better.", reward:"Ransomware Resilience" },
  { id:"defending-systems-124", tier:"Beginner", topic:"Defending Systems", prompt:"Why are backups important against ransomware?", options:["Backups prevent all phishing emails","Backups automatically arrest attackers","Backups remove the need for patching","Backups can support recovery if files are encrypted or destroyed"], correct:3, explain:"Good backups reduce pressure and improve recovery options during ransomware incidents.", reward:"Ransomware Resilience" },
  { id:"defending-systems-125", tier:"Beginner", topic:"Defending Systems", prompt:"What is logging used for in system defense?", options:["Recording events so activity can be monitored and investigated","Making computers physically quieter","Deleting evidence after an alert","Replacing system updates"], correct:0, explain:"Logs create visibility for detection, investigation, and accountability.", reward:"Log Sense" },
  { id:"defending-systems-126", tier:"Beginner", topic:"Defending Systems", prompt:"Why should important logs be centralized?", options:["Central logs are always smaller","Centralization helps preserve and search logs even if one host is affected","Central logs replace all backups","Centralization disables monitoring"], correct:1, explain:"Central logging helps investigation and makes logs harder to lose from one compromised host.", reward:"Central Logging" },
  { id:"defending-systems-127", tier:"Beginner", topic:"Defending Systems", prompt:"What is a SIEM commonly used for?", options:["Replacing endpoint protection","Changing user passwords","Collecting, searching, correlating, and alerting on security logs","Encrypting every network packet"], correct:2, explain:"A SIEM helps defenders analyze security events from many sources.", reward:"SIEM Basics" },
  { id:"defending-systems-128", tier:"Beginner", topic:"Defending Systems", prompt:"Why is time synchronization important for logs?", options:["It changes passwords automatically","It prevents all malware","It disables old accounts","It helps correlate events accurately across systems"], correct:3, explain:"Accurate timestamps make timelines and correlation more reliable.", reward:"Timeline Sense" },
  { id:"defending-systems-129", tier:"Beginner", topic:"Defending Systems", prompt:"What is network segmentation?", options:["Separating networks or systems to limit unnecessary communication","Deleting all routers","Making every device public","Replacing MFA"], correct:0, explain:"Segmentation limits movement and reduces blast radius.", reward:"Segmentation Sense" },
  { id:"defending-systems-130", tier:"Beginner", topic:"Defending Systems", prompt:"Why is segmentation useful after a compromise?", options:["Segmentation makes attackers faster","It can limit lateral movement and spread","Segmentation disables all logs","It removes the need for incident response"], correct:1, explain:"Good segmentation can contain damage by limiting reachability.", reward:"Containment Sense" },
  { id:"defending-systems-131", tier:"Beginner", topic:"Defending Systems", prompt:"What is a firewall used for in system defense?", options:["Creating user passwords","Backing up files","Controlling allowed and blocked traffic","Replacing EDR"], correct:2, explain:"Firewalls enforce traffic rules between systems or networks.", reward:"Firewall Basics" },
  { id:"defending-systems-132", tier:"Beginner", topic:"Defending Systems", prompt:"Why should firewall rules be reviewed?", options:["Rules cannot affect security","Rules are always correct forever","Rules remove all risk automatically","Old or broad rules may leave unnecessary access open"], correct:3, explain:"Firewall rules can become stale, overly broad, or risky over time.", reward:"Firewall Review" },
  { id:"defending-systems-133", tier:"Beginner", topic:"Defending Systems", prompt:"What is an allowlist?", options:["A list of approved items, such as applications, domains, or actions","A list of deleted files","A list of all passwords","A list of random alerts"], correct:0, explain:"Allowlisting permits known approved items while blocking or limiting others.", reward:"Allowlist Sense" },
  { id:"defending-systems-134", tier:"Beginner", topic:"Defending Systems", prompt:"What is application allowlisting used for?", options:["Allowing every program to run","Permitting only approved applications to execute","Disabling all logging","Removing endpoint protection"], correct:1, explain:"Application allowlisting can reduce unauthorized or unknown program execution.", reward:"Application Control" },
  { id:"defending-systems-135", tier:"Beginner", topic:"Defending Systems", prompt:"What is a blocklist?", options:["A list of approved users only","A backup schedule","A list of known bad or denied items","A patch management server"], correct:2, explain:"Blocklists deny known unwanted items such as malicious domains or hashes.", reward:"Blocklist Sense" },
  { id:"defending-systems-136", tier:"Beginner", topic:"Defending Systems", prompt:"Why is relying only on blocklists limited?", options:["Blocklists always catch everything","Blocklists prevent all zero-day threats","Blocklists replace monitoring","New or changed threats may not be listed yet"], correct:3, explain:"Blocklists are useful but cannot cover every new or modified threat.", reward:"Defense Depth" },
  { id:"defending-systems-137", tier:"Beginner", topic:"Defending Systems", prompt:"What is defense in depth?", options:["Using multiple layers of security controls","Using one perfect security product","Turning off all unused logs","Giving everyone admin rights"], correct:0, explain:"Defense in depth means using layered controls so one failure is not total failure.", reward:"Defense Depth" },
  { id:"defending-systems-138", tier:"Beginner", topic:"Defending Systems", prompt:"Why is no single security control enough?", options:["Controls cannot work together","Every control has limits, gaps, or failure modes","Multiple controls always reduce security","Logs replace controls"], correct:1, explain:"Layered controls help cover weaknesses in individual defenses.", reward:"Defense Depth" },
  { id:"defending-systems-139", tier:"Beginner", topic:"Defending Systems", prompt:"What is security awareness training used for?", options:["Replacing all technical controls","Teaching users to recognize and respond to common risks","Disabling MFA","Deleting suspicious emails automatically"], correct:2, explain:"Training helps users avoid or report threats such as phishing.", reward:"Awareness" },
  { id:"defending-systems-140", tier:"Beginner", topic:"Defending Systems", prompt:"Why should users report suspicious emails?", options:["Reports always prove compromise","Reports remove the need for mail filtering","Reports disable malware automatically","Reports help security teams investigate and protect others"], correct:3, explain:"User reports can reveal phishing campaigns early.", reward:"Phishing Defense" },
  { id:"defending-systems-141", tier:"Beginner", topic:"Defending Systems", prompt:"What is incident response preparation?", options:["Planning roles, tools, contacts, and steps before an incident happens","Waiting until an incident starts to decide everything","Deleting old playbooks","Disabling alerts during attacks"], correct:0, explain:"Preparation helps teams respond faster and with less confusion.", reward:"IR Ready" },
  { id:"defending-systems-142", tier:"Beginner", topic:"Defending Systems", prompt:"Why should incident response playbooks be practiced?", options:["Practice makes playbooks unnecessary","Practice reveals gaps before a real incident","Practice disables monitoring","Practice prevents every attack"], correct:1, explain:"Exercises help teams find problems in procedures and responsibilities.", reward:"IR Ready" },
  { id:"defending-systems-143", tier:"Beginner", topic:"Defending Systems", prompt:"What is a tabletop exercise?", options:["A firewall rule test only","A backup file format","A discussion-based incident response practice scenario","A password spraying tool"], correct:2, explain:"Tabletops let teams walk through incident decisions and communication.", reward:"IR Ready" },
  { id:"defending-systems-144", tier:"Beginner", topic:"Defending Systems", prompt:"Why should contact lists be ready before incidents?", options:["Incidents never require communication","Contact lists replace logs","Contacts are only needed after recovery","Fast communication matters during urgent response"], correct:3, explain:"Knowing who to call saves time during incidents.", reward:"IR Ready" },
  { id:"defending-systems-145", tier:"Beginner", topic:"Defending Systems", prompt:"What is asset inventory?", options:["A record of systems, devices, software, accounts, or services owned or used","A list of passwords","A malware family name","A DNS error"], correct:0, explain:"Asset inventory helps defenders know what exists and what needs protection.", reward:"Asset Inventory" },
  { id:"defending-systems-146", tier:"Beginner", topic:"Defending Systems", prompt:"Why is asset inventory important?", options:["Unknown assets are easier to patch","You cannot protect or patch what you do not know exists","Inventory removes the need for monitoring","Inventory makes all assets secure automatically"], correct:1, explain:"Visibility is the foundation for patching, monitoring, and risk management.", reward:"Asset Inventory" },
  { id:"defending-systems-147", tier:"Beginner", topic:"Defending Systems", prompt:"What is configuration management?", options:["Changing screen colors","Creating user nicknames","Tracking and controlling system settings over time","Deleting old alerts"], correct:2, explain:"Configuration management helps keep systems consistent and secure.", reward:"Config Management" },
  { id:"defending-systems-148", tier:"Beginner", topic:"Defending Systems", prompt:"Why are secure baselines useful?", options:["They make every system identical forever","They remove the need for patching","They disable all customization","They define approved secure settings for systems"], correct:3, explain:"Baselines help standardize secure configuration.", reward:"Secure Baseline" },
  { id:"defending-systems-149", tier:"Beginner", topic:"Defending Systems", prompt:"What is a security baseline?", options:["A defined set of expected secure settings or controls","A password reset email","A malicious file hash","A public IP address"], correct:0, explain:"Baselines give teams a standard to configure and measure against.", reward:"Secure Baseline" },
  { id:"defending-systems-150", tier:"Beginner", topic:"Defending Systems", prompt:"Why should baseline drift be monitored?", options:["Drift always improves security","Systems can move away from approved secure configuration over time","Baseline drift prevents all attacks","Drift only affects screen settings"], correct:1, explain:"Monitoring drift helps catch risky or unauthorized changes.", reward:"Config Management" },
  { id:"defending-systems-151", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should patching be prioritized by risk instead of only by age?", options:["Older patches are always more important","Risk considers exploitability, exposure, asset criticality, and business impact","Risk prioritization removes the need to patch","Patch age cannot be measured"], correct:1, explain:"Risk-based patching focuses effort where compromise would matter most.", reward:"Risk-Based Patching" },
  { id:"defending-systems-152", tier:"Intermediate", topic:"Defending Systems", prompt:"What makes an internet-facing vulnerability more urgent?", options:["Internet exposure can allow external attackers to reach it more easily","Internet-facing systems cannot be attacked","External exposure reduces risk","Only internal systems need patches"], correct:0, explain:"Reachability from the internet often increases urgency.", reward:"Risk-Based Patching" },
  { id:"defending-systems-153", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should patching be tested before broad deployment?", options:["Testing makes vulnerabilities worse","Testing always prevents all outages","Testing can catch compatibility or stability issues before wide impact","Testing replaces backups"], correct:2, explain:"Patch testing reduces the risk of breaking important systems.", reward:"Patch Management" },
  { id:"defending-systems-154", tier:"Intermediate", topic:"Defending Systems", prompt:"What should be tracked in patch management?", options:["Only the patch file name","Only the vendor logo","Only the keyboard language","Affected assets, patch status, risk, exceptions, and deadlines"], correct:3, explain:"Tracking makes patch progress and remaining risk visible.", reward:"Patch Management" },
  { id:"defending-systems-155", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should patch exceptions be documented?", options:["Exceptions leave known risk and need ownership, reason, and review date","Exceptions make systems fully secure","Exceptions should always be permanent","Exceptions remove the need for monitoring"], correct:0, explain:"Documented exceptions prevent forgotten risk from becoming unmanaged exposure.", reward:"Risk Management" },
  { id:"defending-systems-156", tier:"Intermediate", topic:"Defending Systems", prompt:"What is compensating control?", options:["A control that makes a system faster","An alternative control used to reduce risk when the preferred control cannot be applied","A password chosen by finance","A deleted firewall rule"], correct:1, explain:"Compensating controls reduce risk when direct fixes are delayed or impossible.", reward:"Risk Management" },
  { id:"defending-systems-157", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a useful compensating control when a patch cannot be applied immediately?", options:["Ignore the vulnerability","Disable all logging","Limit exposure with firewall rules, monitoring, or service restrictions","Give all users admin rights"], correct:2, explain:"Reducing reachability and increasing monitoring can lower risk until patching is possible.", reward:"Risk Management" },
  { id:"defending-systems-158", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should privileged access be reviewed regularly?", options:["Privileges cannot be abused","Reviews make accounts impossible to use","Privileged accounts never change","Access needs change and excessive privileges increase impact"], correct:3, explain:"Access reviews help keep privileged permissions justified and current.", reward:"Privileged Access" },
  { id:"defending-systems-159", tier:"Intermediate", topic:"Defending Systems", prompt:"What is privileged access management?", options:["Managing, limiting, monitoring, and approving high-impact access","Giving every user admin rights","Deleting all admin accounts","Replacing MFA"], correct:0, explain:"PAM helps control powerful access and reduce abuse risk.", reward:"Privileged Access" },
  { id:"defending-systems-160", tier:"Intermediate", topic:"Defending Systems", prompt:"Why use separate admin accounts for administration?", options:["They make usernames shorter","They separate daily user activity from privileged actions for control and auditing","They remove all risk from admin work","They prevent all phishing"], correct:1, explain:"Separate admin accounts make privilege use clearer and easier to monitor.", reward:"Privileged Access" },
  { id:"defending-systems-161", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should admin sessions be logged?", options:["Logging slows every admin task permanently","Admin logs replace backups","They provide accountability and evidence for high-impact actions","Admin sessions cannot be abused"], correct:2, explain:"Privileged activity should be traceable.", reward:"Privileged Access" },
  { id:"defending-systems-162", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should remote admin access be restricted?", options:["Remote access is never useful","Remote access cannot be logged","Only attackers use remote access","It can provide powerful control if exposed or abused"], correct:3, explain:"Remote admin access should be limited, monitored, and protected.", reward:"Remote Access" },
  { id:"defending-systems-163", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should RDP be protected carefully?", options:["It can allow interactive remote control of systems","RDP cannot be attacked","RDP replaces MFA","RDP is only used for DNS"], correct:0, explain:"Exposed or weak RDP can be abused for unauthorized access.", reward:"Remote Access" },
  { id:"defending-systems-164", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a safer approach for administrative access to servers?", options:["Expose admin ports to the whole internet","Use VPN, jump hosts, MFA, logging, and restricted source access","Use shared passwords for convenience","Disable all admin logs"], correct:1, explain:"Administrative access should use layered access controls and monitoring.", reward:"Remote Access" },
  { id:"defending-systems-165", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should service accounts be controlled carefully?", options:["Service accounts cannot be compromised","Service accounts only change wallpaper","They often have persistent access and may be abused if credentials leak","Service accounts never authenticate"], correct:2, explain:"Service accounts need ownership, least privilege, and monitoring.", reward:"Service Account Care" },
  { id:"defending-systems-166", tier:"Intermediate", topic:"Defending Systems", prompt:"What should service account reviews include?", options:["Only whether the account has a nice name","Only the account creation month","Only the user's department","Owner, purpose, permissions, credential age, and usage pattern"], correct:3, explain:"Service account reviews help remove stale or excessive access.", reward:"Service Account Care" },
  { id:"defending-systems-167", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should secrets not be stored in plain text files?", options:["Plain text secrets can be easily read if the file is exposed","Plain text files cannot be copied","Secrets in files expire automatically","Plain text secrets improve auditing"], correct:0, explain:"Secrets should be stored in protected secret-management systems where possible.", reward:"Secret Safety" },
  { id:"defending-systems-168", tier:"Intermediate", topic:"Defending Systems", prompt:"What is secret rotation?", options:["Renaming a server","Replacing credentials or keys with new ones","Changing DNS TTL values","Moving logs to another folder"], correct:1, explain:"Rotating secrets limits the useful lifetime of exposed credentials.", reward:"Secret Safety" },
  { id:"defending-systems-169", tier:"Intermediate", topic:"Defending Systems", prompt:"When should secrets be rotated urgently?", options:["Only when the server restarts","Only once per decade","When they are exposed, suspected leaked, or no longer trusted","Whenever a user changes wallpaper"], correct:2, explain:"Exposed secrets should be treated as compromised.", reward:"Secret Safety" },
  { id:"defending-systems-170", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should developers avoid committing secrets to repositories?", options:["Repositories cannot store text","Secrets in repos cannot be used","Repository secrets make code faster","Secrets may be copied, logged, or exposed to many people and systems"], correct:3, explain:"Secrets in repositories can spread widely and persist in history.", reward:"Secret Safety" },
  { id:"defending-systems-171", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is application control useful?", options:["It can limit execution to approved software and reduce unauthorized code execution","It disables all user accounts","It replaces patching completely","It removes the need for backups"], correct:0, explain:"Application control can block unknown or unwanted programs from running.", reward:"Application Control" },
  { id:"defending-systems-172", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a risk of poorly planned application allowlisting?", options:["It always blocks only malware","It may block legitimate business software or create operational disruption","It prevents all alerts","It removes the need for testing"], correct:1, explain:"Allowlisting needs testing and exceptions management.", reward:"Application Control" },
  { id:"defending-systems-173", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is PowerShell logging useful?", options:["It prevents all script execution","It replaces endpoint protection","It can show script execution, commands, and suspicious administrative activity","It deletes encoded commands"], correct:2, explain:"PowerShell logging gives defenders visibility into script-based activity.", reward:"Script Visibility" },
  { id:"defending-systems-174", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should script execution be controlled?", options:["Scripts can never be useful","Scripts are always malicious","Scripts cannot be logged","Scripts can automate powerful actions and may be abused"], correct:3, explain:"Script controls reduce misuse while still allowing approved administration.", reward:"Script Control" },
  { id:"defending-systems-175", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a secure configuration review?", options:["Checking whether system settings match approved security expectations","Checking only the desktop theme","Deleting all local accounts","Running any random command"], correct:0, explain:"Configuration reviews find risky settings and drift.", reward:"Config Management" },
  { id:"defending-systems-176", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is configuration drift risky?", options:["Drift always improves security","Systems may move away from secure baselines without anyone noticing","Drift prevents logging","Drift makes patching unnecessary"], correct:1, explain:"Uncontrolled changes can weaken defenses or create inconsistency.", reward:"Config Management" },
  { id:"defending-systems-177", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should local firewall settings be managed?", options:["Local firewalls cannot block anything","Local firewalls are only decorative","They help control inbound and outbound traffic on individual systems","Local firewalls replace identity controls"], correct:2, explain:"Host firewalls add another layer of traffic control.", reward:"Host Firewall" },
  { id:"defending-systems-178", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a risk of allowing all inbound traffic to a workstation?", options:["It makes the device impossible to scan","It improves least privilege","It prevents malware from running","It exposes unnecessary services and increases attack surface"], correct:3, explain:"Workstations usually should not accept broad inbound traffic.", reward:"Host Firewall" },
  { id:"defending-systems-179", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should USB device use be controlled in some environments?", options:["Removable media can introduce malware or enable data theft","USB devices cannot store files","USB controls remove the need for backups","USB ports only charge phones"], correct:0, explain:"Removable media can be a security and data-loss risk.", reward:"Device Control" },
  { id:"defending-systems-180", tier:"Intermediate", topic:"Defending Systems", prompt:"What is device control?", options:["Changing the monitor stand","Managing which external devices can connect or be used","Deleting all drivers","Disabling all keyboards"], correct:1, explain:"Device control helps manage risks from USB drives, peripherals, and removable media.", reward:"Device Control" },
  { id:"defending-systems-181", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should disk encryption be used on laptops?", options:["It makes laptops faster","It prevents all phishing","It helps protect data if the laptop is lost or stolen","It replaces user authentication"], correct:2, explain:"Disk encryption protects stored data from offline access.", reward:"Data Protection" },
  { id:"defending-systems-182", tier:"Intermediate", topic:"Defending Systems", prompt:"What is data loss prevention designed to help with?", options:["Assigning IP addresses","Replacing endpoint protection","Creating new passwords","Detecting or preventing unauthorized sensitive data movement"], correct:3, explain:"DLP helps protect sensitive data from accidental or intentional exposure.", reward:"Data Protection" },
  { id:"defending-systems-183", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should sensitive data be classified?", options:["Classification helps apply appropriate protection and handling rules","Classification makes data public","Classification deletes old files","Classification replaces backups"], correct:0, explain:"Data classification helps match controls to sensitivity.", reward:"Data Protection" },
  { id:"defending-systems-184", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should access to sensitive data be monitored?", options:["Sensitive data cannot be misused","Monitoring can detect unusual or unauthorized access","Monitoring prevents all mistakes","Sensitive files never move"], correct:1, explain:"Sensitive access monitoring helps detect misuse or exposure.", reward:"Data Protection" },
  { id:"defending-systems-185", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a useful control for reducing phishing impact?", options:["Remove all email accounts","Give users local admin rights","Email filtering, user reporting, MFA, and safe attachment handling","Disable all security awareness"], correct:2, explain:"Phishing defense works best with multiple layers.", reward:"Phishing Defense" },
  { id:"defending-systems-186", tier:"Advanced", topic:"Defending Systems", prompt:"A critical internet-facing server has an actively exploited vulnerability. What should defenders prioritize?", options:["Assess exposure, patch or mitigate quickly, monitor for exploitation, and confirm compromise status","Wait for the next quarterly cycle without mitigation","Disable all logs to reduce noise","Ignore it if the server is currently online"], correct:0, explain:"Active exploitation plus exposure and criticality makes urgent action necessary.", reward:"Risk-Based Patching" },
  { id:"defending-systems-187", tier:"Advanced", topic:"Defending Systems", prompt:"Why should patch priority consider exploit activity?", options:["Exploit activity shows attackers may already be using the weakness","Exploit activity makes patches unnecessary","Exploit activity only matters for test systems","Exploit activity cannot be tracked"], correct:1, explain:"Known exploitation increases real-world risk.", reward:"Risk-Based Patching" },
  { id:"defending-systems-188", tier:"Advanced", topic:"Defending Systems", prompt:"A patch cannot be installed immediately on a production system. What is a mature response?", options:["Ignore the risk forever","Give all users admin access","Apply compensating controls, document risk acceptance, monitor closely, and schedule remediation","Delete vulnerability reports"], correct:2, explain:"Temporary mitigation should be owned, documented, and followed by real remediation.", reward:"Risk Management" },
  { id:"defending-systems-189", tier:"Advanced", topic:"Defending Systems", prompt:"Why should EDR exclusions be tightly controlled?", options:["Exclusions can create blind spots attackers may abuse","Exclusions always improve detection","Exclusions cannot affect security","Exclusions replace tuning"], correct:0, explain:"Overly broad exclusions can hide malicious activity.", reward:"EDR Control" },
  { id:"defending-systems-190", tier:"Advanced", topic:"Defending Systems", prompt:"What should be reviewed before approving an EDR exclusion?", options:["Only whether the requester is friendly","Business need, scope, path/process, risk, expiration, and monitoring alternatives","Only the file icon","Whether the alert title is long"], correct:1, explain:"Exclusions should be narrow, justified, and reviewed.", reward:"EDR Control" },
  { id:"defending-systems-191", tier:"Advanced", topic:"Defending Systems", prompt:"Why is backup immutability important during ransomware response?", options:["It makes backups impossible to restore","It prevents all malware execution","It helps prevent attackers from modifying or deleting recovery copies","It replaces endpoint isolation"], correct:2, explain:"Immutable backups are harder for attackers to destroy.", reward:"Ransomware Resilience" },
  { id:"defending-systems-192", tier:"Advanced", topic:"Defending Systems", prompt:"What should a ransomware resilience plan include?", options:["Only an antivirus product name","Only a password reset list","Only screenshots of servers","Tested backups, segmentation, monitoring, least privilege, and response procedures"], correct:3, explain:"Ransomware resilience needs layered prevention, detection, containment, and recovery.", reward:"Ransomware Resilience" },
  { id:"defending-systems-193", tier:"Advanced", topic:"Defending Systems", prompt:"Why should privileged access be just-in-time when possible?", options:["It reduces the time window where powerful access exists","It makes all accounts anonymous","It prevents all phishing","It disables auditing"], correct:0, explain:"Temporary privilege reduces standing access risk.", reward:"Privileged Access" },
  { id:"defending-systems-194", tier:"Advanced", topic:"Defending Systems", prompt:"Why should security baselines be measured continuously?", options:["Baselines never change","Continuous measurement helps detect drift, exceptions, and unauthorized changes","Measurement replaces remediation","Continuous checks disable systems"], correct:1, explain:"Continuous assessment helps keep secure configuration real, not just documented.", reward:"Secure Baseline" },
  { id:"defending-systems-195", tier:"Advanced", topic:"Defending Systems", prompt:"Why is detection coverage mapping useful?", options:["It proves all threats are detected","It replaces incident response","It shows which techniques or behaviors have monitoring and where gaps remain","It disables false positives"], correct:2, explain:"Coverage mapping helps prioritize new detections and telemetry improvements.", reward:"Detection Coverage" },
  { id:"defending-systems-196", tier:"Advanced", topic:"Defending Systems", prompt:"What is a risk of collecting logs without reviewing their quality?", options:["Logs are always complete","Log quality never affects investigations","Poor logs make every alert true positive","Missing fields or bad parsing can weaken detection and response"], correct:3, explain:"Telemetry must be complete, parsed, and usable.", reward:"Log Quality" },
  { id:"defending-systems-197", tier:"Advanced", topic:"Defending Systems", prompt:"Why should incident response lessons feed back into system hardening?", options:["Incidents reveal real weaknesses that can be fixed or controlled","Lessons learned replace patching","Hardening is unrelated to incidents","Only attackers learn from incidents"], correct:0, explain:"Good defense improves after learning from real events.", reward:"Lessons Learned" },
  { id:"defending-systems-198", tier:"Advanced", topic:"Defending Systems", prompt:"What is a mature way to validate security controls?", options:["Assume tools work because they are installed","Test controls with safe simulations, audits, and expected detection checks","Disable controls during testing","Only read vendor marketing pages"], correct:1, explain:"Validation confirms controls actually work in the real environment.", reward:"Control Validation" },
  { id:"defending-systems-199", tier:"Advanced", topic:"Defending Systems", prompt:"Why should system defense be risk-based?", options:["Risk-based defense ignores critical systems","It aligns effort with likelihood, exposure, asset value, and business impact","Risk makes security unnecessary","All systems always need identical controls"], correct:2, explain:"Risk-based thinking helps prioritize limited time and resources.", reward:"Risk Management" },
  { id:"defending-systems-200", tier:"Advanced", topic:"Defending Systems", prompt:"What is the strongest mindset for defending systems?", options:["Install one tool and stop improving","Wait for attackers before preparing","Assume users will never make mistakes","Layer controls, validate them, monitor continuously, and improve after failures"], correct:3, explain:"Strong defense is layered, measured, and continuously improved.", reward:"Defense Mindset" },
  { id:"defending-systems-201", tier:"Beginner", topic:"Defending Systems", prompt:"What is the purpose of access control?", options:["To limit who can access systems, data, or actions","To make all data public","To delete old logs","To replace backups"], correct:0, explain:"Access control helps ensure only authorized users and systems can reach resources.", reward:"Access Control" },
  { id:"defending-systems-202", tier:"Beginner", topic:"Defending Systems", prompt:"What is authentication?", options:["Deleting unused accounts","Proving identity before access is granted","Encrypting every file","Blocking all network traffic"], correct:1, explain:"Authentication verifies who a user or system claims to be.", reward:"Auth Basics" },
  { id:"defending-systems-203", tier:"Beginner", topic:"Defending Systems", prompt:"What is authorization?", options:["Resetting a password","Logging out of a system","Deciding what an authenticated user is allowed to do","Installing security updates"], correct:2, explain:"Authorization controls permissions after identity is verified.", reward:"Auth Basics" },
  { id:"defending-systems-204", tier:"Beginner", topic:"Defending Systems", prompt:"Why should permissions be reviewed?", options:["Permissions never change","Reviews remove the need for passwords","Reviews disable MFA","Users may keep access they no longer need"], correct:3, explain:"Permission reviews help remove excessive or outdated access.", reward:"Access Review" },
  { id:"defending-systems-205", tier:"Beginner", topic:"Defending Systems", prompt:"What is an access review?", options:["A check that users and accounts still have appropriate permissions","A malware scan only","A DNS lookup","A backup restore test"], correct:0, explain:"Access reviews confirm that permissions are still justified.", reward:"Access Review" },
  { id:"defending-systems-206", tier:"Beginner", topic:"Defending Systems", prompt:"Why should terminated employees lose access quickly?", options:["Old access improves productivity","Former access can be abused if it remains active","It makes patching unnecessary","It disables logging"], correct:1, explain:"Removing access promptly reduces insider and account misuse risk.", reward:"Account Hygiene" },
  { id:"defending-systems-207", tier:"Beginner", topic:"Defending Systems", prompt:"What is account provisioning?", options:["Deleting all accounts","Blocking all logins","Creating or granting access for users based on need","Encrypting hard drives"], correct:2, explain:"Provisioning gives users the access they need to do their job.", reward:"Account Lifecycle" },
  { id:"defending-systems-208", tier:"Beginner", topic:"Defending Systems", prompt:"What is account deprovisioning?", options:["Adding new permissions","Making an account administrator","Changing the desktop theme","Removing access when it is no longer needed"], correct:3, explain:"Deprovisioning removes access when someone leaves or changes role.", reward:"Account Lifecycle" },
  { id:"defending-systems-209", tier:"Beginner", topic:"Defending Systems", prompt:"Why should shared accounts be avoided when possible?", options:["They make accountability harder","They improve audit quality","They prevent credential theft","They remove the need for MFA"], correct:0, explain:"Shared accounts make it difficult to know who performed an action.", reward:"Accountability" },
  { id:"defending-systems-210", tier:"Beginner", topic:"Defending Systems", prompt:"What is role-based access control?", options:["Access based only on password length","Access assigned according to job roles or responsibilities","Access based on screen size","Access granted randomly"], correct:1, explain:"RBAC assigns permissions based on roles instead of one-off decisions.", reward:"RBAC Basics" },
  { id:"defending-systems-211", tier:"Beginner", topic:"Defending Systems", prompt:"Why is role-based access useful?", options:["It removes the need for all approvals","It makes every user an admin","It helps keep permissions consistent and easier to manage","It disables all user accounts"], correct:2, explain:"Roles make access easier to review and manage.", reward:"RBAC Basics" },
  { id:"defending-systems-212", tier:"Beginner", topic:"Defending Systems", prompt:"What is separation of duties?", options:["Giving one user all permissions","Removing all managers from approvals","Deleting all audit logs","Splitting sensitive tasks so one person cannot control everything alone"], correct:3, explain:"Separation of duties reduces fraud and misuse risk.", reward:"Governance Sense" },
  { id:"defending-systems-213", tier:"Beginner", topic:"Defending Systems", prompt:"Why should administrative actions be logged?", options:["They provide accountability and investigation evidence","They make systems slower on purpose","They replace all approvals","They prevent every mistake"], correct:0, explain:"Admin logs show who changed what and when.", reward:"Audit Trail" },
  { id:"defending-systems-214", tier:"Beginner", topic:"Defending Systems", prompt:"What is an audit trail?", options:["A list of random alerts","A record of actions that can be reviewed later","A password reset token","A blocked website category"], correct:1, explain:"Audit trails support accountability, investigations, and compliance.", reward:"Audit Trail" },
  { id:"defending-systems-215", tier:"Beginner", topic:"Defending Systems", prompt:"Why should audit logs be protected from tampering?", options:["Tampering makes logs more accurate","Audit logs are never useful","Attackers may try to hide their actions by changing or deleting logs","Logs should always be editable by everyone"], correct:2, explain:"Protected logs are more reliable during investigations.", reward:"Log Protection" },
  { id:"defending-systems-216", tier:"Beginner", topic:"Defending Systems", prompt:"What is log retention?", options:["Deleting all logs immediately","Changing log colors","Blocking all alerts","Keeping logs for a defined period"], correct:3, explain:"Retention defines how long logs remain available for investigations and requirements.", reward:"Log Sense" },
  { id:"defending-systems-217", tier:"Beginner", topic:"Defending Systems", prompt:"Why should log retention be planned?", options:["Investigations may need older events to understand scope and timeline","Old logs are never useful","Retention prevents all malware","Retention replaces backups"], correct:0, explain:"If logs are deleted too soon, important evidence may be unavailable.", reward:"Log Sense" },
  { id:"defending-systems-218", tier:"Beginner", topic:"Defending Systems", prompt:"What is a security policy?", options:["A random alert title","A documented rule or expectation for protecting systems and data","A malware sample","A DNS cache entry"], correct:1, explain:"Policies define expected security behavior and responsibilities.", reward:"Policy Sense" },
  { id:"defending-systems-219", tier:"Beginner", topic:"Defending Systems", prompt:"Why should security policies be understandable?", options:["Policies should be confusing to prevent misuse","Only lawyers should understand them","People are more likely to follow clear rules","Unclear policies prevent all incidents"], correct:2, explain:"Clear policies are easier to follow and enforce.", reward:"Policy Sense" },
  { id:"defending-systems-220", tier:"Beginner", topic:"Defending Systems", prompt:"What is an acceptable use policy?", options:["A firewall blocklist","A backup schedule","A vulnerability scanner","Rules for how users may use company systems and resources"], correct:3, explain:"Acceptable use policies set boundaries for safe and appropriate technology use.", reward:"Policy Sense" },
  { id:"defending-systems-221", tier:"Beginner", topic:"Defending Systems", prompt:"What is change management?", options:["Controlling and documenting changes to systems or services","Changing passwords every minute","Deleting all software updates","Renaming every server"], correct:0, explain:"Change management reduces risk from uncontrolled changes.", reward:"Change Control" },
  { id:"defending-systems-222", tier:"Beginner", topic:"Defending Systems", prompt:"Why should major system changes be approved?", options:["Approval makes all changes perfect","Approval helps manage risk, timing, rollback, and accountability","Approval replaces testing","Approval disables monitoring"], correct:1, explain:"Approval ensures risky changes are reviewed before they affect systems.", reward:"Change Control" },
  { id:"defending-systems-223", tier:"Beginner", topic:"Defending Systems", prompt:"What is a rollback plan?", options:["A plan to remove all logs","A plan to give users admin rights","A plan to reverse a change if something goes wrong","A plan to skip testing"], correct:2, explain:"Rollback planning helps recover from failed or harmful changes.", reward:"Rollback Sense" },
  { id:"defending-systems-224", tier:"Beginner", topic:"Defending Systems", prompt:"Why should changes be tested before production?", options:["Production is the safest test area","Testing is unnecessary for small changes","Testing makes systems vulnerable","Testing can catch problems before users or critical services are affected"], correct:3, explain:"Testing lowers the risk of outages or security problems.", reward:"Change Control" },
  { id:"defending-systems-225", tier:"Beginner", topic:"Defending Systems", prompt:"What is asset ownership?", options:["Assigning responsibility for a system, service, or data set","Deleting old systems","Making every device public","Removing all users"], correct:0, explain:"Owners help make decisions about risk, maintenance, and access.", reward:"Asset Inventory" },
  { id:"defending-systems-226", tier:"Beginner", topic:"Defending Systems", prompt:"Why should every important asset have an owner?", options:["Owners make systems immune to compromise","Owners help confirm purpose, access, impact, and maintenance needs","Owners remove the need for logging","Owners disable vulnerabilities"], correct:1, explain:"Asset owners provide business and operational context.", reward:"Asset Inventory" },
  { id:"defending-systems-227", tier:"Beginner", topic:"Defending Systems", prompt:"What is software inventory?", options:["A list of user birthdays","A list of installed or approved software","A list of firewall colors","A list of keyboard layouts"], correct:2, explain:"Software inventory helps manage patching, licensing, and security risk.", reward:"Software Inventory" },
  { id:"defending-systems-228", tier:"Beginner", topic:"Defending Systems", prompt:"Why is unknown software risky?", options:["Unknown software always improves security","Unknown software never runs","Unknown software cannot connect to networks","It may be unpatched, unauthorized, or malicious"], correct:3, explain:"Unknown software creates visibility and security risk.", reward:"Software Inventory" },
  { id:"defending-systems-229", tier:"Beginner", topic:"Defending Systems", prompt:"What is a secure baseline for workstations?", options:["A standard set of approved security settings for workstation devices","A list of user hobbies","A malware report","A backup cable"], correct:0, explain:"Workstation baselines help keep devices consistently protected.", reward:"Secure Baseline" },
  { id:"defending-systems-230", tier:"Beginner", topic:"Defending Systems", prompt:"Why should workstation screens lock automatically?", options:["It makes screens brighter","It helps prevent unauthorized access when users leave devices unattended","It deletes suspicious files","It replaces MFA"], correct:1, explain:"Auto-locking reduces physical access risk.", reward:"Device Hygiene" },
  { id:"defending-systems-231", tier:"Beginner", topic:"Defending Systems", prompt:"Why should laptops use disk encryption?", options:["It makes Wi-Fi faster","It disables phishing","It protects data if the device is lost or stolen","It replaces backups"], correct:2, explain:"Encryption helps prevent offline access to stored data.", reward:"Data Protection" },
  { id:"defending-systems-232", tier:"Beginner", topic:"Defending Systems", prompt:"Why should lost devices be reported quickly?", options:["Lost devices are never risky","Reporting disables all attacks automatically","Reports are only for inventory charts","Security teams can take actions such as locking, wiping, or monitoring access"], correct:3, explain:"Fast reporting reduces risk from lost or stolen devices.", reward:"Device Hygiene" },
  { id:"defending-systems-233", tier:"Beginner", topic:"Defending Systems", prompt:"What is mobile device management used for?", options:["Managing settings, security, and access for mobile devices","Creating DNS records","Deleting network switches","Replacing all passwords"], correct:0, explain:"MDM helps enforce security controls on phones, tablets, and laptops.", reward:"Device Management" },
  { id:"defending-systems-234", tier:"Beginner", topic:"Defending Systems", prompt:"Why should personal devices be controlled before accessing company data?", options:["Personal devices are always safer","Unmanaged devices may lack required security controls","Personal devices cannot be compromised","Controls remove the need for user training"], correct:1, explain:"Device trust matters when accessing sensitive resources.", reward:"Device Management" },
  { id:"defending-systems-235", tier:"Beginner", topic:"Defending Systems", prompt:"What is phishing-resistant MFA designed to reduce?", options:["Normal software updates","Backup failures","Credential phishing and MFA bypass risk","Disk encryption"], correct:2, explain:"Phishing-resistant MFA makes stolen passwords and fake login pages less effective.", reward:"MFA Shield" },
  { id:"defending-systems-236", tier:"Beginner", topic:"Defending Systems", prompt:"Why should users avoid approving unexpected MFA prompts?", options:["MFA prompts cannot be abused","Unexpected prompts mean the system is updating","MFA approvals are only decorative","It may allow an attacker with a stolen password to sign in"], correct:3, explain:"Unexpected MFA prompts can indicate credential misuse or MFA fatigue attacks.", reward:"MFA Shield" },
  { id:"defending-systems-237", tier:"Beginner", topic:"Defending Systems", prompt:"What is phishing simulation used for?", options:["Training users and measuring response to phishing-like emails","Sending real malware to users","Replacing email filters","Deleting mailboxes"], correct:0, explain:"Simulations help improve awareness and reporting habits.", reward:"Phishing Defense" },
  { id:"defending-systems-238", tier:"Beginner", topic:"Defending Systems", prompt:"Why should phishing reports be easy for users to submit?", options:["Reports are never useful","Easy reporting helps security teams respond faster to suspicious messages","Reporting replaces mail filtering","Only admins can spot phishing"], correct:1, explain:"Simple reporting increases the chance users report suspicious emails.", reward:"Phishing Defense" },
  { id:"defending-systems-239", tier:"Beginner", topic:"Defending Systems", prompt:"What is email filtering used for?", options:["Changing email fonts","Backing up all workstations","Blocking or flagging suspicious messages before they reach users","Disabling MFA"], correct:2, explain:"Email filtering helps reduce phishing, spam, and malicious attachments.", reward:"Email Defense" },
  { id:"defending-systems-240", tier:"Beginner", topic:"Defending Systems", prompt:"Why should suspicious attachments be handled carefully?", options:["Attachments cannot contain malware","Opening attachments is always safe","Attachments automatically patch systems","They may contain malware, scripts, or exploit documents"], correct:3, explain:"Attachments should be scanned and handled according to safe procedures.", reward:"Email Defense" },
  { id:"defending-systems-241", tier:"Beginner", topic:"Defending Systems", prompt:"What is web filtering used for?", options:["Blocking or warning on risky websites and categories","Changing browser colors","Creating passwords","Replacing endpoint logs"], correct:0, explain:"Web filtering helps reduce access to known risky or unwanted sites.", reward:"Web Defense" },
  { id:"defending-systems-242", tier:"Beginner", topic:"Defending Systems", prompt:"Why should browsers be kept updated?", options:["Updates only change icons","Browser updates can fix security vulnerabilities used by malicious sites","Browser updates remove the need for DNS","Updated browsers block all phishing"], correct:1, explain:"Browsers are common attack targets and need regular updates.", reward:"Patch Sense" },
  { id:"defending-systems-243", tier:"Beginner", topic:"Defending Systems", prompt:"Why should risky browser extensions be controlled?", options:["Extensions cannot access data","Extensions are always safe","Extensions may access browsing data or weaken security","Extensions replace antivirus"], correct:2, explain:"Extensions can introduce privacy and security risk.", reward:"Browser Defense" },
  { id:"defending-systems-244", tier:"Beginner", topic:"Defending Systems", prompt:"What is secure browsing behavior?", options:["Ignoring certificate warnings","Downloading every attachment","Using the same password everywhere","Avoiding suspicious sites, checking URLs, and respecting security warnings"], correct:3, explain:"Safe browsing habits reduce exposure to web-based attacks.", reward:"Web Defense" },
  { id:"defending-systems-245", tier:"Beginner", topic:"Defending Systems", prompt:"What is data minimization?", options:["Keeping only the data that is needed for a legitimate purpose","Copying all data everywhere","Storing passwords in plain text","Disabling backups"], correct:0, explain:"Less unnecessary data means less exposure if something goes wrong.", reward:"Data Protection" },
  { id:"defending-systems-246", tier:"Beginner", topic:"Defending Systems", prompt:"Why should sensitive data access be limited?", options:["Sensitive data should be public","Limiting access reduces exposure and misuse risk","Limiting access disables all users","Sensitive data cannot be stolen"], correct:1, explain:"Only people and systems with a real need should access sensitive data.", reward:"Data Protection" },
  { id:"defending-systems-247", tier:"Beginner", topic:"Defending Systems", prompt:"What is encryption at rest?", options:["Encrypting data while it is stored","Encrypting only keyboard input","Encrypting only DNS queries","Deleting all old data"], correct:0, explain:"Encryption at rest protects stored data if storage is accessed improperly.", reward:"Encryption Basics" },
  { id:"defending-systems-248", tier:"Beginner", topic:"Defending Systems", prompt:"What is encryption in transit?", options:["Backing up data once per year","Making all files read-only","Deleting data after use","Protecting data while it moves across networks"], correct:3, explain:"Encryption in transit protects communication between systems.", reward:"Encryption Basics" },
  { id:"defending-systems-249", tier:"Beginner", topic:"Defending Systems", prompt:"Why should recovery plans be documented?", options:["During incidents, clear recovery steps reduce confusion and downtime","Recovery plans prevent all attacks","Documentation replaces backups","Recovery plans should be secret from responders"], correct:0, explain:"Documented recovery procedures help teams act under pressure.", reward:"Recovery Ready" },
  { id:"defending-systems-250", tier:"Beginner", topic:"Defending Systems", prompt:"What is business continuity planning?", options:["Changing all passwords weekly","Planning how critical operations continue during disruptions","Deleting unused accounts","Blocking all internet access"], correct:1, explain:"Business continuity focuses on keeping essential services running.", reward:"Resilience" },
  { id:"defending-systems-251", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should organizations define recovery time objectives?", options:["They define how quickly systems should be restored after disruption","They replace all backups","They make attacks impossible","They only apply to printers"], correct:0, explain:"Recovery time objectives help set recovery expectations and priorities.", reward:"Recovery Ready" },
  { id:"defending-systems-252", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a recovery point objective?", options:["The number of users in a group","The acceptable amount of data loss measured in time","The maximum password length","The time a firewall rule was created"], correct:1, explain:"RPO describes how much data loss is acceptable based on backup frequency.", reward:"Recovery Ready" },
  { id:"defending-systems-253", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should backup access be restricted?", options:["Backups are never sensitive","Backups cannot be deleted","Attackers may target backups to prevent recovery","Backup access replaces MFA"], correct:2, explain:"Backups need protection because they are critical for recovery.", reward:"Backup Basics" },
  { id:"defending-systems-254", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should restore procedures be tested?", options:["Testing restores is only for auditors","Restore tests make backups useless","Restore procedures never fail","Recovery may fail if backup data, permissions, or steps are broken"], correct:3, explain:"A backup strategy is incomplete without tested restoration.", reward:"Backup Basics" },
  { id:"defending-systems-255", tier:"Intermediate", topic:"Defending Systems", prompt:"What is vulnerability scanning?", options:["Checking systems for known weaknesses or risky configurations","Deleting all files on a system","Creating new user accounts","Encrypting network traffic"], correct:0, explain:"Vulnerability scanners help find issues that need review or remediation.", reward:"Vulnerability Basics" },
  { id:"defending-systems-256", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should scan results be validated?", options:["Scanners are always wrong","Scanners can produce false positives or miss environmental context","Validation makes vulnerabilities worse","Scan results should never be reviewed"], correct:1, explain:"Validation confirms whether findings are real and relevant.", reward:"Vulnerability Basics" },
  { id:"defending-systems-257", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should vulnerability scans be scheduled carefully?", options:["Scans cannot affect systems","Scans only affect passwords","Scans can create load, alerts, or service impact","Scans replace change management"], correct:2, explain:"Scanning should be planned to reduce operational disruption.", reward:"Vulnerability Basics" },
  { id:"defending-systems-258", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should asset criticality affect remediation priority?", options:["Critical assets are always safe","Only low-value systems need fixes","All assets have identical impact","Compromise of critical assets can cause greater damage"], correct:3, explain:"Risk-based remediation prioritizes high-impact assets.", reward:"Risk Management" },
  { id:"defending-systems-259", tier:"Intermediate", topic:"Defending Systems", prompt:"What is exposure management?", options:["Understanding and reducing reachable attack paths and exposed weaknesses","Publishing all internal services","Turning off all controls","Deleting asset inventory"], correct:0, explain:"Exposure management looks at what attackers can reach and abuse.", reward:"Attack Surface" },
  { id:"defending-systems-260", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should internet-facing assets be monitored closely?", options:["They cannot be reached by attackers","They are more exposed to external scanning and exploitation","They never need patching","They do not create logs"], correct:1, explain:"Internet-facing systems are reachable by external threat actors.", reward:"Attack Surface" },
  { id:"defending-systems-261", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is configuration backup useful for network and security devices?", options:["It replaces all firewall rules","It prevents every outage","It helps restore known-good settings after failure or bad change","It disables attacker access"], correct:2, explain:"Configuration backups support recovery and change rollback.", reward:"Recovery Ready" },
  { id:"defending-systems-262", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should configuration backups be protected?", options:["They cannot contain sensitive data","They are only screenshots","They make passwords unnecessary","They may contain secrets, network details, or security settings"], correct:3, explain:"Configuration backups can expose sensitive infrastructure information.", reward:"Data Protection" },
  { id:"defending-systems-263", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should administrative interfaces be limited to trusted networks?", options:["Admin interfaces provide powerful control and should not be broadly reachable","Admin interfaces are always harmless","Trusted networks remove the need for authentication","Admin interfaces cannot be attacked"], correct:0, explain:"Restricting admin interfaces reduces attack surface.", reward:"Remote Access" },
  { id:"defending-systems-264", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a jump server used for?", options:["Replacing DNS","Providing controlled access into restricted systems or networks","Deleting firewall logs","Backing up user photos"], correct:1, explain:"Jump servers centralize and monitor administrative access.", reward:"Remote Access" },
  { id:"defending-systems-265", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should jump server activity be logged?", options:["Jump servers cannot be abused","Logging is only for web servers","It records privileged access paths and administrative actions","Logging disables remote access"], correct:2, explain:"Jump servers are important control points and should have strong audit trails.", reward:"Audit Trail" },
  { id:"defending-systems-266", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should direct access to critical servers be limited?", options:["Critical servers never need maintenance","Direct access improves attacker visibility","Direct access cannot be monitored","Controlled access reduces misuse and improves accountability"], correct:3, explain:"Critical systems should use controlled and monitored access paths.", reward:"Privileged Access" },
  { id:"defending-systems-267", tier:"Intermediate", topic:"Defending Systems", prompt:"What is endpoint isolation used for?", options:["Temporarily cutting a device off from normal network communication during response","Making a device faster","Deleting all files","Replacing backups"], correct:0, explain:"Isolation can limit spread while responders investigate.", reward:"Containment Sense" },
  { id:"defending-systems-268", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should endpoint isolation be used carefully?", options:["It always has no effect","It can disrupt users, services, or evidence collection if done blindly","It prevents all future attacks","It removes the need for scoping"], correct:1, explain:"Isolation is useful but can have operational impact.", reward:"Containment Sense" },
  { id:"defending-systems-269", tier:"Intermediate", topic:"Defending Systems", prompt:"What should be checked before isolating a server when possible?", options:["Only whether the alert is red","Only the hostname length","Business impact, service criticality, evidence needs, and approval path","Only whether the server has a monitor"], correct:2, explain:"Server isolation can affect critical services and should be controlled.", reward:"Containment Sense" },
  { id:"defending-systems-270", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should containment actions be reversible when possible?", options:["Reversibility is never useful","Containment always fails","Reversibility hides evidence","It helps restore service if the action causes unintended impact"], correct:3, explain:"Reversible actions reduce operational risk.", reward:"Rollback Sense" },
  { id:"defending-systems-271", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should detections be tested after enabling new logging?", options:["To confirm useful events are collected and parsed correctly","Testing makes logs disappear","New logging always works perfectly","Testing replaces monitoring"], correct:0, explain:"Telemetry must be validated before relying on it.", reward:"Log Quality" },
  { id:"defending-systems-272", tier:"Intermediate", topic:"Defending Systems", prompt:"What is log parsing?", options:["Deleting old log entries","Turning raw logs into structured fields that can be searched and used","Disabling alerts","Encrypting backups"], correct:1, explain:"Parsing makes logs easier to search, correlate, and alert on.", reward:"Log Quality" },
  { id:"defending-systems-273", tier:"Intermediate", topic:"Defending Systems", prompt:"Why do missing log fields matter?", options:["Fields are only decoration","Missing fields make dashboards prettier","They can weaken detection, triage, and investigation quality","Missing fields prevent all false positives"], correct:2, explain:"Important fields like user, host, process, or IP are often needed for decisions.", reward:"Log Quality" },
  { id:"defending-systems-274", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should logging changes use change control?", options:["Logs cannot affect security","Logging changes are always harmless","Logging changes should never be documented","They can affect visibility, cost, storage, privacy, and detection behavior"], correct:3, explain:"Logging is part of security operations and should be managed.", reward:"Change Control" },
  { id:"defending-systems-275", tier:"Intermediate", topic:"Defending Systems", prompt:"What is secure remote access?", options:["Remote access protected with controls such as MFA, restricted sources, logging, and least privilege","Remote access with shared passwords","Remote access from any IP without monitoring","Remote access that bypasses all policies"], correct:0, explain:"Secure remote access uses layered controls.", reward:"Remote Access" },
  { id:"defending-systems-276", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should VPN access be reviewed?", options:["VPN accounts cannot be compromised","VPN access can expose internal resources if misused","VPN logs are never useful","VPN access replaces endpoint protection"], correct:1, explain:"Remote access should match user need and be monitored.", reward:"Remote Access" },
  { id:"defending-systems-277", tier:"Intermediate", topic:"Defending Systems", prompt:"What is conditional access?", options:["Access with no logging","Access granted randomly","Access based on conditions such as user, device, location, risk, or MFA","Access only based on username length"], correct:2, explain:"Conditional access adapts access decisions to risk and context.", reward:"Access Control" },
  { id:"defending-systems-278", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should device compliance affect access?", options:["Unmanaged devices are always safe","Compliance removes the need for passwords","Device state cannot affect risk","Noncompliant devices may lack required security controls"], correct:3, explain:"Device health and management status affect trust.", reward:"Device Management" },
  { id:"defending-systems-279", tier:"Intermediate", topic:"Defending Systems", prompt:"What is zero trust as a defensive idea?", options:["Continuously verify access instead of trusting by network location alone","Trust every internal device automatically","Remove all authentication","Make all data public"], correct:0, explain:"Zero trust focuses on verification, least privilege, and assumed breach.", reward:"Zero Trust" },
  { id:"defending-systems-280", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is 'inside the network' not enough to trust a device?", options:["Internal devices cannot communicate","Internal devices can be compromised or unauthorized","Internal devices never need monitoring","Internal networks prevent all attacks"], correct:1, explain:"Attackers may gain internal access, so trust should not depend only on location.", reward:"Zero Trust" },
  { id:"defending-systems-281", tier:"Intermediate", topic:"Defending Systems", prompt:"What does 'assume breach' mean?", options:["Ignore all alerts","Assume every user is malicious","Design defenses as if attackers may already have some access","Disable all prevention tools"], correct:2, explain:"Assume breach encourages monitoring, segmentation, and least privilege.", reward:"Zero Trust" },
  { id:"defending-systems-282", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is lateral movement prevention important?", options:["Lateral movement cannot happen","It makes patching unnecessary","It disables phishing","It limits spread after one system or account is compromised"], correct:3, explain:"Limiting lateral movement reduces blast radius.", reward:"Segmentation Sense" },
  { id:"defending-systems-283", tier:"Intermediate", topic:"Defending Systems", prompt:"What control helps reduce lateral movement?", options:["Network segmentation and restricted administrative access","Shared admin passwords","Flat networks with open access","Disabling all firewall logs"], correct:0, explain:"Segmentation and restricted access limit attacker movement.", reward:"Segmentation Sense" },
  { id:"defending-systems-284", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should local administrator passwords be unique per device?", options:["Unique passwords make all devices public","Compromise of one password should not give admin access to many devices","Unique passwords disable patching","Shared passwords improve auditing"], correct:1, explain:"Unique local admin passwords reduce credential reuse risk.", reward:"Credential Defense" },
  { id:"defending-systems-285", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should credential dumping be defended against?", options:["Credential dumping is only a backup process","Dumped credentials cannot be reused","Stolen credentials can enable privilege escalation and lateral movement","Credential dumping improves security"], correct:2, explain:"Credential theft can turn one compromised host into many.", reward:"Credential Defense" },
  { id:"defending-systems-286", tier:"Advanced", topic:"Defending Systems", prompt:"What is a strong strategy for reducing credential theft impact?", options:["Least privilege, MFA, credential isolation, logging, unique admin passwords, and rapid rotation","Using one shared admin password everywhere","Disabling account monitoring","Storing secrets in scripts"], correct:0, explain:"Credential defense needs multiple layers.", reward:"Credential Defense" },
  { id:"defending-systems-287", tier:"Advanced", topic:"Defending Systems", prompt:"Why is attack path analysis useful?", options:["It replaces all controls","It helps identify how an attacker could move from initial access to critical assets","It makes every asset public","It disables vulnerabilities"], correct:1, explain:"Attack path analysis helps prioritize controls that break dangerous paths.", reward:"Attack Path" },
  { id:"defending-systems-288", tier:"Advanced", topic:"Defending Systems", prompt:"What is a dangerous attack path example?", options:["A patched kiosk with no access to internal systems","A guest Wi-Fi network with internet only","A low-privilege workstation path leading to domain admin access through weak controls","A disabled test account with no permissions"], correct:2, explain:"Attack paths matter when small footholds can lead to major compromise.", reward:"Attack Path" },
  { id:"defending-systems-289", tier:"Advanced", topic:"Defending Systems", prompt:"Why should identity controls and endpoint controls be reviewed together?", options:["They are unrelated","Endpoint controls replace identity security","Identity controls prevent all malware","Attackers often combine endpoint compromise with credential or session abuse"], correct:3, explain:"Modern compromises often cross identity and endpoint boundaries.", reward:"Defense Depth" },
  { id:"defending-systems-290", tier:"Advanced", topic:"Defending Systems", prompt:"Why should cloud, endpoint, and identity logs be correlated?", options:["Correlated logs reveal cross-platform attack paths and impact","One log source always tells everything","Correlation makes logs less useful","Only cloud logs matter"], correct:0, explain:"Cross-source visibility helps detect and investigate real attacker behavior.", reward:"Correlation Sense" },
  { id:"defending-systems-291", tier:"Advanced", topic:"Defending Systems", prompt:"What is a risk of excessive EDR exclusions on developer machines?", options:["Developers cannot be attacked","Attackers may abuse excluded paths or tools to avoid detection","Exclusions always improve protection","EDR exclusions are only visual"], correct:1, explain:"Exclusions should be narrow and monitored.", reward:"EDR Control" },
  { id:"defending-systems-292", tier:"Advanced", topic:"Defending Systems", prompt:"Why should production secrets be separated from development environments?", options:["Development systems are always more secure","Production secrets are never sensitive","Development compromise should not automatically expose production access","Separation disables deployment"], correct:2, explain:"Environment separation limits blast radius.", reward:"Secret Safety" },
  { id:"defending-systems-293", tier:"Advanced", topic:"Defending Systems", prompt:"Why should break-glass accounts be protected carefully?", options:["They are low-value accounts","They should be shared publicly","They never need monitoring","They provide emergency high-privilege access and are high-risk if abused"], correct:3, explain:"Break-glass accounts need strong controls, monitoring, and limited use.", reward:"Privileged Access" },
  { id:"defending-systems-294", tier:"Advanced", topic:"Defending Systems", prompt:"What is a mature approach to break-glass accounts?", options:["Protect with strong authentication, monitor use, review regularly, and keep access limited","Use weak passwords so they are easy to remember","Disable all logging for privacy","Use them for daily work"], correct:0, explain:"Emergency access must be available but tightly controlled.", reward:"Privileged Access" },
  { id:"defending-systems-295", tier:"Advanced", topic:"Defending Systems", prompt:"Why should security controls be mapped to business-critical processes?", options:["Business processes do not matter","It ensures controls protect what the organization depends on most","Mapping removes the need for detection","Only low-value systems need controls"], correct:1, explain:"Security work should support the systems and data that matter most.", reward:"Risk Management" },
  { id:"defending-systems-296", tier:"Advanced", topic:"Defending Systems", prompt:"Why should control failures be tracked?", options:["Failures should always be hidden","Tracking failures replaces remediation","They show where prevention, detection, process, or training needs improvement","Failures prove controls are useless"], correct:2, explain:"Control failures are opportunities to improve defense.", reward:"Control Validation" },
  { id:"defending-systems-297", tier:"Advanced", topic:"Defending Systems", prompt:"Why should purple-team or simulation exercises be useful for defenders?", options:["They replace real monitoring","They make attackers harmless","They should only test offensive tools","They validate whether controls detect and prevent realistic behavior"], correct:3, explain:"Safe simulations help test defenses before real attacks.", reward:"Control Validation" },
  { id:"defending-systems-298", tier:"Advanced", topic:"Defending Systems", prompt:"Why should security teams measure mean time to detect and respond?", options:["These metrics show how quickly the organization notices and handles threats","They replace evidence collection","They make patching unnecessary","They prove every alert is correct"], correct:0, explain:"Detection and response speed are important resilience measures.", reward:"Quality Metrics" },
  { id:"defending-systems-299", tier:"Advanced", topic:"Defending Systems", prompt:"What is the risk of optimizing only for speed in defense?", options:["Speed always improves security","Fast action without evidence can cause disruption or miss root cause","Speed makes false positives impossible","Fast response replaces planning"], correct:1, explain:"Defenders need speed, but also accuracy and control.", reward:"Defense Mindset" },
  { id:"defending-systems-300", tier:"Advanced", topic:"Defending Systems", prompt:"What is the goal of continuous improvement in system defense?", options:["To stop documenting security work","To install one tool and never change it","To learn from incidents, tests, and metrics to strengthen controls over time","To remove all monitoring after success"], correct:2, explain:"Defending systems is an ongoing process, not a one-time setup.", reward:"Lessons Learned" },
  { id:"defending-systems-301", tier:"Beginner", topic:"Defending Systems", prompt:"What is the purpose of security monitoring?", options:["To watch for suspicious activity, failures, and signs of compromise","To delete all alerts automatically","To replace all patching","To make systems public"], correct:0, explain:"Monitoring gives defenders visibility into what is happening across systems.", reward:"Monitoring Sense" },
  { id:"defending-systems-302", tier:"Beginner", topic:"Defending Systems", prompt:"Why should important systems generate security logs?", options:["Logs make systems impossible to attack","Logs provide evidence for detection, investigation, and accountability","Logs replace backups","Logs remove the need for MFA"], correct:1, explain:"Security logs help defenders understand what happened and respond properly.", reward:"Log Sense" },
  { id:"defending-systems-303", tier:"Beginner", topic:"Defending Systems", prompt:"What is a security alert?", options:["A random system message","A backup schedule","A notification that activity matched a suspicious or important condition","A password policy only"], correct:2, explain:"Alerts point defenders toward events that may need review.", reward:"Alert Sense" },
  { id:"defending-systems-304", tier:"Beginner", topic:"Defending Systems", prompt:"Why should alerts include useful details?", options:["Details make alerts impossible to close","Details replace all investigation","Details always prove compromise","Details help analysts understand what happened and what to check next"], correct:3, explain:"Good alert details improve triage speed and quality.", reward:"Alert Quality" },
  { id:"defending-systems-305", tier:"Beginner", topic:"Defending Systems", prompt:"What is a detection rule?", options:["Logic that looks for suspicious or important activity in data","A password written on paper","A backup copy of a server","A hardware cable label"], correct:0, explain:"Detection rules identify activity that may need investigation.", reward:"Detection Basics" },
  { id:"defending-systems-306", tier:"Beginner", topic:"Defending Systems", prompt:"Why should detection rules be tested?", options:["Testing makes alerts useless","To confirm they find expected activity without too much noise","Testing deletes logs","Detection rules always work perfectly"], correct:1, explain:"Testing helps confirm the rule is useful and not too noisy.", reward:"Detection Validation" },
  { id:"defending-systems-307", tier:"Beginner", topic:"Defending Systems", prompt:"What is a false positive in detection?", options:["A confirmed malicious event","A missing backup","An alert on benign activity","A disabled user account"], correct:2, explain:"False positives are alerts that fire on harmless or expected behavior.", reward:"Alert Quality" },
  { id:"defending-systems-308", tier:"Beginner", topic:"Defending Systems", prompt:"What is a false negative in detection?", options:["A harmless alert","A duplicate ticket","A successful backup","Malicious or important activity that was missed"], correct:3, explain:"False negatives are dangerous because real activity is not detected.", reward:"Detection Quality" },
  { id:"defending-systems-309", tier:"Beginner", topic:"Defending Systems", prompt:"Why should noisy detections be tuned?", options:["Too much noise can overwhelm analysts and hide real threats","Noise always means compromise","Noisy alerts should never be reviewed","Tuning deletes all evidence"], correct:0, explain:"Tuning improves signal while preserving useful coverage.", reward:"Alert Quality" },
  { id:"defending-systems-310", tier:"Beginner", topic:"Defending Systems", prompt:"Why should detections not be tuned too broadly?", options:["Broad tuning makes every alert true","Overly broad suppression can hide real threats","Tuning prevents all attacks","Broad tuning replaces monitoring"], correct:1, explain:"Tuning must reduce noise without creating blind spots.", reward:"Detection Quality" },
  { id:"defending-systems-311", tier:"Beginner", topic:"Defending Systems", prompt:"What is telemetry in security?", options:["A user password list","A firewall color setting","Data collected from systems for monitoring and analysis","A physical server rack"], correct:2, explain:"Telemetry includes logs, events, metrics, and signals used by defenders.", reward:"Telemetry Sense" },
  { id:"defending-systems-312", tier:"Beginner", topic:"Defending Systems", prompt:"Why should telemetry coverage be reviewed?", options:["Telemetry is always complete","Telemetry replaces patching","Telemetry cannot have gaps","Missing telemetry can prevent detection or investigation"], correct:3, explain:"Coverage reviews help identify blind spots.", reward:"Visibility Gap" },
  { id:"defending-systems-313", tier:"Beginner", topic:"Defending Systems", prompt:"What is a visibility gap?", options:["Missing or incomplete information needed for defense or investigation","A dark monitor","A disabled keyboard","A short hostname"], correct:0, explain:"Visibility gaps make it harder to detect and investigate activity.", reward:"Visibility Gap" },
  { id:"defending-systems-314", tier:"Beginner", topic:"Defending Systems", prompt:"Why should visibility gaps be documented?", options:["Documentation makes gaps disappear automatically","Documented gaps can be prioritized and fixed","Gaps are never important","Gaps should be hidden from teams"], correct:1, explain:"Documenting gaps turns unknown weakness into managed risk.", reward:"Visibility Gap" },
  { id:"defending-systems-315", tier:"Beginner", topic:"Defending Systems", prompt:"What is a security control?", options:["A random alert","A password hint","A measure used to reduce risk","A deleted log file"], correct:2, explain:"Security controls help prevent, detect, or respond to risk.", reward:"Control Sense" },
  { id:"defending-systems-316", tier:"Beginner", topic:"Defending Systems", prompt:"What is a preventive control?", options:["A control used only after compromise","A report written after an incident","A dashboard color setting","A control designed to stop or reduce an unwanted event before it happens"], correct:3, explain:"Preventive controls reduce the chance of bad events occurring.", reward:"Control Sense" },
  { id:"defending-systems-317", tier:"Beginner", topic:"Defending Systems", prompt:"What is a detective control?", options:["A control designed to discover suspicious or unwanted activity","A control that deletes every alert","A control that replaces passwords","A control used only for backups"], correct:0, explain:"Detective controls identify activity that may require investigation.", reward:"Control Sense" },
  { id:"defending-systems-318", tier:"Beginner", topic:"Defending Systems", prompt:"What is a corrective control?", options:["A control that prevents all phishing","A control that helps fix or recover after an issue","A control that makes every user admin","A control that disables logs"], correct:1, explain:"Corrective controls support recovery or remediation after a problem.", reward:"Control Sense" },
  { id:"defending-systems-319", tier:"Beginner", topic:"Defending Systems", prompt:"Which is an example of a preventive control?", options:["Incident report after breach","A screenshot of an alert","MFA for user logins","A lesson learned meeting only"], correct:2, explain:"MFA helps prevent unauthorized access using only a stolen password.", reward:"MFA Shield" },
  { id:"defending-systems-320", tier:"Beginner", topic:"Defending Systems", prompt:"Which is an example of a detective control?", options:["Disk encryption only","A password manager only","A backup restore only","An alert for suspicious login activity"], correct:3, explain:"Suspicious-login alerts help detect possible account compromise.", reward:"Detection Basics" },
  { id:"defending-systems-321", tier:"Beginner", topic:"Defending Systems", prompt:"What is a useful example of a corrective control?", options:["Restoring data from backup after deletion or ransomware","Ignoring alerts","Sharing admin passwords","Disabling MFA"], correct:0, explain:"Corrective controls help recover from or fix security incidents.", reward:"Recovery Ready" },
  { id:"defending-systems-322", tier:"Beginner", topic:"Defending Systems", prompt:"Why should controls be reviewed regularly?", options:["Controls always stay perfect forever","Threats, systems, and business needs change over time","Reviews make controls useless","Controls should never be documented"], correct:1, explain:"Regular review ensures controls still work and remain relevant.", reward:"Control Validation" },
  { id:"defending-systems-323", tier:"Beginner", topic:"Defending Systems", prompt:"What is control validation?", options:["Assuming a control works","Buying a security product","Testing whether a control works as intended","Deleting test results"], correct:2, explain:"Validation confirms that security controls actually function in practice.", reward:"Control Validation" },
  { id:"defending-systems-324", tier:"Beginner", topic:"Defending Systems", prompt:"Why should control failures be investigated?", options:["Failures should be hidden","Failures prove security is impossible","Failures remove the need for improvement","Failures show where defenses need repair or redesign"], correct:3, explain:"A control failure is useful feedback for improvement.", reward:"Lessons Learned" },
  { id:"defending-systems-325", tier:"Beginner", topic:"Defending Systems", prompt:"What is security awareness?", options:["User understanding of security risks and safe behavior","A firewall rule ID","A backup copy of data","A malware family"], correct:0, explain:"Awareness helps users recognize and report risky situations.", reward:"Awareness" },
  { id:"defending-systems-326", tier:"Beginner", topic:"Defending Systems", prompt:"Why should security training be repeated?", options:["Training once prevents all attacks","People forget, threats change, and habits need reinforcement","Repeated training disables malware","Training replaces monitoring"], correct:1, explain:"Regular training keeps security behavior fresh and relevant.", reward:"Awareness" },
  { id:"defending-systems-327", tier:"Beginner", topic:"Defending Systems", prompt:"What is a good security culture?", options:["Users hide mistakes","Security teams blame everyone","People report issues early and treat security as shared responsibility","Only managers think about security"], correct:2, explain:"Healthy security culture encourages reporting, learning, and responsibility.", reward:"Security Culture" },
  { id:"defending-systems-328", tier:"Beginner", topic:"Defending Systems", prompt:"Why should users feel safe reporting mistakes?", options:["Mistakes are never security-relevant","Reports should always be punished","Reporting mistakes slows response","Early reporting helps security teams reduce damage"], correct:3, explain:"Punishing honest reports can make users hide incidents.", reward:"Security Culture" },
  { id:"defending-systems-329", tier:"Beginner", topic:"Defending Systems", prompt:"What is a security exception?", options:["An approved deviation from normal security requirements","A malware alert","A deleted user account","A DNS response"], correct:0, explain:"Exceptions should be documented, justified, and reviewed.", reward:"Risk Management" },
  { id:"defending-systems-330", tier:"Beginner", topic:"Defending Systems", prompt:"Why should security exceptions expire or be reviewed?", options:["Exceptions should last forever","Old exceptions can become forgotten risk","Exceptions remove all risk","Reviewing exceptions breaks systems"], correct:1, explain:"Exception reviews keep temporary risk from becoming permanent.", reward:"Risk Management" },
  { id:"defending-systems-331", tier:"Beginner", topic:"Defending Systems", prompt:"What is risk acceptance?", options:["Pretending risk does not exist","Deleting evidence of risk","Formally acknowledging and accepting a known risk","Removing all controls"], correct:2, explain:"Risk acceptance should be conscious, documented, and owned.", reward:"Risk Management" },
  { id:"defending-systems-332", tier:"Beginner", topic:"Defending Systems", prompt:"Why should risk acceptance be documented?", options:["Documentation makes risk disappear","Documentation replaces remediation","Documentation prevents alerts","It records who accepted the risk, why, and for how long"], correct:3, explain:"Documented risk acceptance creates accountability.", reward:"Risk Management" },
  { id:"defending-systems-333", tier:"Beginner", topic:"Defending Systems", prompt:"What is secure disposal?", options:["Safely removing data from systems or media before reuse or disposal","Throwing drives in a drawer","Leaving old accounts active","Sharing old laptops without wiping"], correct:0, explain:"Secure disposal prevents old data from being recovered or exposed.", reward:"Data Protection" },
  { id:"defending-systems-334", tier:"Beginner", topic:"Defending Systems", prompt:"Why should old hard drives be wiped or destroyed properly?", options:["Old drives never contain data","They may contain sensitive data that can be recovered","Wiping drives disables phishing","Drive disposal replaces backups"], correct:1, explain:"Storage media can retain data after normal deletion.", reward:"Data Protection" },
  { id:"defending-systems-335", tier:"Beginner", topic:"Defending Systems", prompt:"What is data retention?", options:["Making all data public forever","Deleting every file immediately","Keeping data for a defined period based on need or policy","Disabling file access"], correct:2, explain:"Retention rules help manage legal, business, privacy, and storage needs.", reward:"Data Protection" },
  { id:"defending-systems-336", tier:"Beginner", topic:"Defending Systems", prompt:"Why should data not be kept forever by default?", options:["Data cannot be searched later","Old data is always worthless","Keeping data improves all security controls","Unneeded data increases exposure if systems are compromised"], correct:3, explain:"Data minimization reduces the amount that can be exposed.", reward:"Data Protection" },
  { id:"defending-systems-337", tier:"Beginner", topic:"Defending Systems", prompt:"What is a secure default setting?", options:["A setting that starts in a safer configuration without extra user action","A setting that disables all accounts","A setting that makes logs public","A setting that allows every connection"], correct:0, explain:"Secure defaults reduce risk before users make changes.", reward:"Secure Baseline" },
  { id:"defending-systems-338", tier:"Beginner", topic:"Defending Systems", prompt:"Why are insecure defaults dangerous?", options:["They always patch themselves","They may expose systems before anyone changes them","They remove all attack surface","They prevent misconfiguration"], correct:1, explain:"Insecure defaults can create risk immediately after deployment.", reward:"Secure Baseline" },
  { id:"defending-systems-339", tier:"Beginner", topic:"Defending Systems", prompt:"What is configuration drift?", options:["A system moving away from approved settings over time","A user changing a password","A DNS lookup","A successful backup"], correct:0, explain:"Drift can create inconsistent or insecure system states.", reward:"Config Management" },
  { id:"defending-systems-340", tier:"Beginner", topic:"Defending Systems", prompt:"Why should configuration drift be corrected?", options:["Drift always improves security","Drift cannot affect systems","Approved baselines may be weakened if drift is ignored","Correcting drift disables all logging"], correct:2, explain:"Correction helps restore intended secure settings.", reward:"Config Management" },
  { id:"defending-systems-341", tier:"Beginner", topic:"Defending Systems", prompt:"What is secure build process?", options:["A repeatable process for deploying systems with approved settings and controls","Randomly installing software","Disabling all security tools","Sharing admin passwords"], correct:0, explain:"Secure builds reduce inconsistent and risky deployments.", reward:"Secure Build" },
  { id:"defending-systems-342", tier:"Beginner", topic:"Defending Systems", prompt:"Why should new systems be hardened before production use?", options:["Production systems cannot be attacked","Early hardening reduces exposure before the system handles real users or data","Hardening prevents all future patches","Hardening makes logging unnecessary"], correct:1, explain:"Systems should not enter production with unnecessary risk.", reward:"Secure Build" },
  { id:"defending-systems-343", tier:"Beginner", topic:"Defending Systems", prompt:"What is environment separation?", options:["Using separate spaces for production, testing, and development","Putting all secrets in one folder","Giving developers production admin by default","Mixing test data with real customer data"], correct:0, explain:"Environment separation limits accidental or unauthorized impact.", reward:"Environment Safety" },
  { id:"defending-systems-344", tier:"Beginner", topic:"Defending Systems", prompt:"Why should production systems be protected more carefully than test systems?", options:["Production data and services usually have greater business impact","Test systems are always malicious","Production systems cannot fail","Production systems need no monitoring"], correct:0, explain:"Production impact is usually higher, so controls and access should be stronger.", reward:"Environment Safety" },
  { id:"defending-systems-345", tier:"Beginner", topic:"Defending Systems", prompt:"Why should test environments avoid real sensitive data when possible?", options:["Sensitive test data improves safety","Real sensitive data increases exposure if the test environment is weaker","Test systems cannot leak data","Sensitive data disables testing"], correct:1, explain:"Using fake or masked data reduces privacy and exposure risk.", reward:"Data Protection" },
  { id:"defending-systems-346", tier:"Beginner", topic:"Defending Systems", prompt:"What is data masking?", options:["Deleting every database","Making sensitive data unreadable or replaced for safer use","Turning off encryption","Sharing raw secrets"], correct:1, explain:"Masking protects sensitive values while preserving useful structure.", reward:"Data Protection" },
  { id:"defending-systems-347", tier:"Beginner", topic:"Defending Systems", prompt:"What is the purpose of secrets management?", options:["To store and control access to passwords, keys, and tokens safely","To post passwords in chat","To remove all authentication","To make all keys permanent"], correct:0, explain:"Secrets management protects credentials and reduces exposure.", reward:"Secret Safety" },
  { id:"defending-systems-348", tier:"Beginner", topic:"Defending Systems", prompt:"Why should secrets have limited permissions?", options:["Limited permissions reduce damage if the secret is exposed","Secrets should always be global admin","Limited permissions prevent rotation","Secrets cannot be abused"], correct:0, explain:"Least privilege applies to secrets as well as users.", reward:"Secret Safety" },
  { id:"defending-systems-349", tier:"Beginner", topic:"Defending Systems", prompt:"What is a security review?", options:["A review of design, code, configuration, or process to find risk","A random password reset","A deleted alert","A DNS cache flush"], correct:0, explain:"Security reviews help catch issues before they become incidents.", reward:"Review Sense" },
  { id:"defending-systems-350", tier:"Beginner", topic:"Defending Systems", prompt:"Why should high-risk changes receive security review?", options:["High-risk changes cannot fail","Review can catch security impact before deployment","Review removes all business impact","Security reviews should only happen after incidents"], correct:1, explain:"Review before deployment reduces the chance of avoidable exposure.", reward:"Review Sense" },
  { id:"defending-systems-351", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should security teams define minimum logging standards?", options:["Minimum standards make logs impossible to search","They ensure important systems produce usable evidence for detection and response","Standards replace endpoint security","Only test systems need logs"], correct:1, explain:"Logging standards improve consistency across systems.", reward:"Log Quality" },
  { id:"defending-systems-352", tier:"Intermediate", topic:"Defending Systems", prompt:"What should a minimum logging standard include?", options:["Only the system hostname","Required event types, fields, retention, time sync, and forwarding expectations","Only dashboard colors","Only the product logo"], correct:1, explain:"Good standards define what data is needed and how it should be handled.", reward:"Log Quality" },
  { id:"defending-systems-353", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should logs include user and host identifiers?", options:["Identifiers make logs prettier","Identifiers prevent all attacks","They help connect activity to accounts and systems","Identifiers replace incident response"], correct:2, explain:"User and host fields are essential for triage and correlation.", reward:"Log Quality" },
  { id:"defending-systems-354", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a risk of collecting sensitive data in logs?", options:["Logs cannot contain sensitive data","Sensitive logs always improve privacy","Sensitive logs remove all risk","Logs may expose secrets, personal data, or internal details if not protected"], correct:3, explain:"Logs should be useful but not unnecessarily expose sensitive information.", reward:"Data Care" },
  { id:"defending-systems-355", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should logging access be restricted?", options:["Logs may contain sensitive evidence and operational information","Logs are never useful","Everyone should edit logs freely","Restricted access prevents monitoring"], correct:0, explain:"Log access should match need and responsibility.", reward:"Log Protection" },
  { id:"defending-systems-356", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should logs be protected from deletion?", options:["Deleted logs make investigations easier","Attackers may delete logs to hide activity","Logs are only temporary decoration","Deleting logs improves detection"], correct:1, explain:"Log protection supports reliable investigations.", reward:"Log Protection" },
  { id:"defending-systems-357", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a useful control against log tampering?", options:["Give all users log admin rights","Store all logs only on the local host","Forward logs to protected centralized storage","Disable timestamps"], correct:2, explain:"Centralized protected logs are harder for a compromised host to destroy.", reward:"Log Protection" },
  { id:"defending-systems-358", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should administrators not use shared accounts?", options:["Shared accounts make log attribution and accountability harder","Shared accounts always improve security","Shared accounts prevent insider risk","Shared accounts remove need for approvals"], correct:0, explain:"Individual accounts make actions traceable.", reward:"Accountability" },
  { id:"defending-systems-359", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should privileged actions require stronger controls?", options:["Privileged actions cannot harm systems","Privileged actions have greater potential impact if misused","Privileged actions should never be logged","Privileged users cannot make mistakes"], correct:1, explain:"High-impact actions deserve stronger authentication, approval, and auditing.", reward:"Privileged Access" },
  { id:"defending-systems-360", tier:"Intermediate", topic:"Defending Systems", prompt:"What is just-in-time access?", options:["Permanent admin access for every user","Temporary access granted only when needed","Access without approval","A disabled audit trail"], correct:1, explain:"JIT access reduces standing privilege.", reward:"Privileged Access" },
  { id:"defending-systems-361", tier:"Intermediate", topic:"Defending Systems", prompt:"What is just-enough administration?", options:["Giving users all permissions","Giving no one any access","Granting only the permissions needed for a specific task","Using one admin password everywhere"], correct:2, explain:"Just-enough administration applies least privilege to admin work.", reward:"Least Privilege" },
  { id:"defending-systems-362", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should privileged sessions be monitored?", options:["Monitoring prevents all mistakes automatically","Privileged sessions are always safe","Monitoring replaces MFA","They can reveal misuse, mistakes, or compromise of powerful access"], correct:3, explain:"Privileged access should be visible and accountable.", reward:"Privileged Access" },
  { id:"defending-systems-363", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should system administrators use separate daily and admin accounts?", options:["It reduces the chance daily activities expose privileged credentials","It makes administration impossible","It removes the need for passwords","It prevents all phishing"], correct:0, explain:"Separate accounts reduce accidental exposure of privileged access.", reward:"Privileged Access" },
  { id:"defending-systems-364", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should production access be limited?", options:["Production access cannot affect real users","Mistakes or misuse in production can have high business impact","Production access is only for testing","Production systems do not hold data"], correct:1, explain:"Production systems require stronger access controls because impact is higher.", reward:"Environment Safety" },
  { id:"defending-systems-365", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a common risk of using production data in development?", options:["Development environments may have weaker controls and expose real data","Production data improves privacy","Development systems are always more secure","Production data cannot be copied"], correct:0, explain:"Development environments often have different security controls than production.", reward:"Data Protection" },
  { id:"defending-systems-366", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should deployment pipelines be protected?", options:["Pipelines cannot change systems","Pipelines only affect documentation","Compromised pipelines can push malicious or broken changes at scale","Pipelines remove the need for code review"], correct:2, explain:"Build and deployment systems are powerful and high-value.", reward:"Pipeline Defense" },
  { id:"defending-systems-367", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a secure software supply chain concern?", options:["Only whether the logo looks professional","Whether dependencies, build systems, and releases can be trusted","Only the filename length","Only the monitor used by developers"], correct:1, explain:"Supply-chain security protects the path from source code to deployed software.", reward:"Supply Chain" },
  { id:"defending-systems-368", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should dependencies be reviewed?", options:["Dependencies are always safe","Dependencies cannot contain vulnerabilities","Third-party code can introduce vulnerabilities, license risk, or malicious behavior","Dependencies replace testing"], correct:2, explain:"External packages become part of the system risk.", reward:"Supply Chain" },
  { id:"defending-systems-369", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a software bill of materials useful for?", options:["Listing software components and dependencies in an application","Deleting vulnerable packages automatically","Replacing all patching","Disabling code review"], correct:0, explain:"An SBOM helps understand what components are present.", reward:"Supply Chain" },
  { id:"defending-systems-370", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should build systems have limited secrets?", options:["Build systems cannot leak data","Build systems should be global admins","Build compromise could expose secrets or deploy malicious artifacts","Secrets make builds faster"], correct:2, explain:"Build systems are high-value and should follow least privilege.", reward:"Pipeline Defense" },
  { id:"defending-systems-371", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should code signing keys be protected?", options:["They can be abused to make malicious code appear trusted","Code signing keys are public by design","Code signing prevents all vulnerabilities","Keys cannot be stolen"], correct:0, explain:"Signing keys are high-value secrets and need strong protection.", reward:"Supply Chain" },
  { id:"defending-systems-372", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should deployment approvals be required for sensitive systems?", options:["Approvals make deployments impossible","Approvals provide review and accountability before high-impact changes","Approvals replace testing","Approvals disable monitoring"], correct:1, explain:"Sensitive deployments should not be uncontrolled.", reward:"Change Control" },
  { id:"defending-systems-373", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should rollback be tested for deployments?", options:["Rollback is always automatic","Rollback cannot fail","Untested rollback may fail during real outages","Rollback replaces monitoring"], correct:2, explain:"Rollback should be reliable before it is needed under pressure.", reward:"Rollback Sense" },
  { id:"defending-systems-374", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a canary deployment used for?", options:["Deploying everywhere at once without monitoring","Deleting old versions immediately","Disabling all users during release","Rolling out a change to a small group first to reduce risk"], correct:3, explain:"Canary deployments limit impact while monitoring for problems.", reward:"Change Control" },
  { id:"defending-systems-375", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should security controls be included in system design?", options:["Fixing security later can be harder, costlier, and less reliable","Security design prevents all bugs","Security controls make systems unusable","Design never affects risk"], correct:0, explain:"Security is stronger when built in early.", reward:"Secure Design" },
  { id:"defending-systems-376", tier:"Intermediate", topic:"Defending Systems", prompt:"What is threat modeling?", options:["Drawing only network cables","Thinking through possible threats and defenses before or during design","Deleting old vulnerabilities","Running random commands"], correct:1, explain:"Threat modeling helps identify risks and controls before deployment.", reward:"Threat Modeling" },
  { id:"defending-systems-377", tier:"Intermediate", topic:"Defending Systems", prompt:"Why is threat modeling useful?", options:["It replaces monitoring","It proves attackers cannot win","It helps identify likely attack paths and needed controls","It removes the need for patching"], correct:2, explain:"Threat modeling makes risk visible during design.", reward:"Threat Modeling" },
  { id:"defending-systems-378", tier:"Intermediate", topic:"Defending Systems", prompt:"What should threat modeling consider?", options:["Only the product name","Only the color scheme","Only user preferences","Assets, entry points, trust boundaries, threats, and mitigations"], correct:3, explain:"Threat modeling examines how a system can be attacked and defended.", reward:"Threat Modeling" },
  { id:"defending-systems-379", tier:"Intermediate", topic:"Defending Systems", prompt:"What is a trust boundary?", options:["A point where data or access crosses between different trust levels","A password reset page","A backup folder","A deleted user group"], correct:0, explain:"Trust boundaries are places where stronger validation or controls are often needed.", reward:"Threat Modeling" },
  { id:"defending-systems-380", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should input validation be part of system defense?", options:["Input validation makes all users admin","Untrusted input can be used to exploit systems if not handled safely","Input validation disables logging","Input validation replaces backups"], correct:1, explain:"Systems should not blindly trust input from users or other systems.", reward:"Secure Design" },
  { id:"defending-systems-381", tier:"Intermediate", topic:"Defending Systems", prompt:"What is secure error handling?", options:["Showing full secrets in errors","Hiding all errors from logs","Providing useful errors without leaking sensitive internal details","Crashing every time"], correct:2, explain:"Error handling should help troubleshooting without exposing too much.", reward:"Secure Design" },
  { id:"defending-systems-382", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should sensitive actions require reauthentication or confirmation?", options:["Sensitive actions cannot cause harm","Confirmation replaces authorization","It makes all actions public","It reduces accidental or unauthorized high-impact changes"], correct:3, explain:"Extra checks help protect high-impact actions.", reward:"Access Control" },
  { id:"defending-systems-383", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should APIs enforce authorization on the server side?", options:["Clients can be modified, so the server must enforce access rules","Client-side checks are always enough","Authorization is only visual","APIs cannot expose data"], correct:0, explain:"The server must enforce permissions because clients are not trusted.", reward:"Secure Design" },
  { id:"defending-systems-384", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should rate limiting be used on sensitive endpoints?", options:["Rate limiting makes passwords shorter","It can reduce brute force, abuse, and automated overload","Rate limiting disables authentication","Rate limiting removes the need for logs"], correct:1, explain:"Rate limits help control abusive or excessive requests.", reward:"Abuse Prevention" },
  { id:"defending-systems-385", tier:"Intermediate", topic:"Defending Systems", prompt:"Why should security reviews include abuse cases?", options:["Abuse cases are only for attackers","Abuse cases make systems less secure","They help defenders think about how features could be misused","Abuse cases replace testing"], correct:2, explain:"Abuse-case thinking improves defensive design.", reward:"Secure Design" },
  { id:"defending-systems-386", tier:"Advanced", topic:"Defending Systems", prompt:"Why should defenders validate controls against real attack techniques?", options:["Realistic validation reveals whether controls work against behavior attackers actually use","Controls always work if purchased","Attack techniques are irrelevant to defense","Validation should only check screenshots"], correct:0, explain:"Controls should be tested against realistic behavior, not assumptions.", reward:"Control Validation" },
  { id:"defending-systems-387", tier:"Advanced", topic:"Defending Systems", prompt:"What is the value of detection engineering feedback from SOC analysts?", options:["SOC feedback should be ignored","It improves rule logic, context, severity, and investigation guidance","It deletes false positives automatically","It replaces telemetry"], correct:1, explain:"Analysts see how detections work in practice and can improve them.", reward:"Detection Coverage" },
  { id:"defending-systems-388", tier:"Advanced", topic:"Defending Systems", prompt:"Why should organizations test incident response under realistic pressure?", options:["Pressure makes all plans useless","Incidents never require decisions","Exercises reveal gaps in communication, authority, tools, and timing","Testing replaces recovery planning"], correct:2, explain:"Realistic exercises expose problems before real incidents do.", reward:"IR Ready" },
  { id:"defending-systems-389", tier:"Advanced", topic:"Defending Systems", prompt:"What is a risk of over-centralized security ownership?", options:["Everyone becomes too secure","Security incidents stop happening","Users report too many issues","Teams may think security is only the security team's job"], correct:3, explain:"Security works better when responsibility is shared across teams.", reward:"Security Culture" },
  { id:"defending-systems-390", tier:"Advanced", topic:"Defending Systems", prompt:"Why should security metrics include both activity and outcomes?", options:["Activity alone may not show whether risk is actually reduced","Outcomes are never useful","Metrics should only count tickets","Outcomes replace security work"], correct:0, explain:"Good metrics show whether controls and processes are improving defense.", reward:"Quality Metrics" },
  { id:"defending-systems-391", tier:"Advanced", topic:"Defending Systems", prompt:"Why is mean time to remediate useful?", options:["It measures how quickly identified issues are fixed","It replaces vulnerability scanning","It proves no risk exists","It only applies to printers"], correct:1, explain:"Remediation speed shows how long known risk remains open.", reward:"Quality Metrics" },
  { id:"defending-systems-392", tier:"Advanced", topic:"Defending Systems", prompt:"Why should security teams avoid vanity metrics?", options:["They are always too difficult to calculate","They can look impressive without proving risk reduction","They replace all dashboards","They prevent management reporting"], correct:2, explain:"Metrics should support decisions, not just look good.", reward:"Quality Metrics" },
  { id:"defending-systems-393", tier:"Advanced", topic:"Defending Systems", prompt:"What is a strong sign that defensive maturity is improving?", options:["More unreviewed exceptions","Less logging over time","More shared administrator accounts","Fewer repeat failures because root causes are fixed"], correct:3, explain:"Maturity improves when lessons reduce repeated problems.", reward:"Lessons Learned" },
  { id:"defending-systems-394", tier:"Advanced", topic:"Defending Systems", prompt:"Why should security architecture consider blast radius?", options:["Blast radius describes how far damage can spread from one failure or compromise","Blast radius is only a physical safety term","Blast radius replaces authentication","Blast radius means all systems are isolated perfectly"], correct:0, explain:"Reducing blast radius limits impact from compromise.", reward:"Defense Depth" },
  { id:"defending-systems-395", tier:"Advanced", topic:"Defending Systems", prompt:"How can defenders reduce blast radius?", options:["Give every system the same admin password","Use segmentation, least privilege, environment separation, and scoped access","Disable all logging","Put all data in one shared folder"], correct:1, explain:"Blast radius is reduced by limiting reachability and permissions.", reward:"Defense Depth" },
  { id:"defending-systems-396", tier:"Advanced", topic:"Defending Systems", prompt:"Why should security exceptions be visible to risk owners?", options:["Risk owners need to understand and accept remaining exposure","Exceptions should be hidden from owners","Visible exceptions prevent all attacks","Risk owners never make decisions"], correct:0, explain:"Risk ownership requires visibility into accepted exceptions.", reward:"Risk Management" },
  { id:"defending-systems-397", tier:"Advanced", topic:"Defending Systems", prompt:"Why should defenders consider attacker objectives, not only tools?", options:["Tools are the only thing that matters","Objectives reveal what assets and paths attackers may target","Objectives remove the need for controls","Attackers never change tools"], correct:1, explain:"Tool names change, but attacker goals drive behavior.", reward:"Threat Modeling" },
  { id:"defending-systems-398", tier:"Advanced", topic:"Defending Systems", prompt:"What is a mature response after discovering a major control gap?", options:["Document risk, assign ownership, apply temporary mitigations, and plan durable remediation","Ignore it until an incident happens","Delete the finding","Disable related alerts"], correct:0, explain:"Control gaps should be managed and fixed, not hidden.", reward:"Risk Management" },
  { id:"defending-systems-399", tier:"Advanced", topic:"Defending Systems", prompt:"Why should defenders review incidents for root cause?", options:["Root cause review helps fix underlying weaknesses instead of only symptoms","Root cause never matters after containment","Root cause review replaces recovery","Root cause review is only for auditors"], correct:1, explain:"Root cause work helps prevent repeat incidents.", reward:"Lessons Learned" },
  { id:"defending-systems-400", tier:"Advanced", topic:"Defending Systems", prompt:"What is the strongest long-term approach to defending systems?", options:["Install tools once and never review them","Trust internal systems by default forever","Continuously reduce exposure, validate controls, improve visibility, and learn from incidents","Disable alerts to avoid noise"], correct:2, explain:"Strong defense is continuous, evidence-based, and improvement-focused.", reward:"Defense Mindset" },
];

if (typeof module !== "undefined" && module.exports) module.exports = DEFENDING_SYSTEMS_QUESTIONS;
